  ui_story_5026_50260101_1_dialog_content = "¿PlayerName, PlayerName?",
  ui_story_5026_50260101_2_dialog_content = "¡Oye! ¡Ya es hora de que te despiertes!",
  ui_story_5026_50260101_3_dialog_content = "(¿Quién es ese que habla?)",
  ui_story_5026_50260101_4_dialog_content = "El tiempo de redención del premio se acabará si no te levantas.",
  ui_story_5026_50260101_5_dialog_content = "¿Tiempo de redención del premio?",
