  ui_story_5026_50260101_57_dialog_content = "<size=33>Jaja...</size>",
  ui_story_5026_50260101_58_dialog_content = "No parece muy poderoso, pero no puedo lidiar con eso exactamente con solo una caña de pescar...",
  ui_story_5026_50260101_59_dialog_content = "¡Ay! ¡No huyas!",
  ui_story_5026_50260101_60_dialog_content = "<color=#e8d9bb>Timbre...</color>",
  ui_story_5026_50260101_61_dialog_content = "¡Fufufu!",
  ui_story_5026_50260101_62_dialog_content = "Parece que llegué justo a tiempo.",
  ui_story_5026_50260101_63_dialog_content = "¡Templo no conformista! ¡Gracias por eso!",
  ui_story_5026_50260101_64_dialog_content = "Pan comido. Estaba más preocupado de que mi visita repentina te causara problemas, PlayerName.",
  ui_story_5026_50260101_65_dialog_content = "¡De nada! Sin ti, este parche de hierba podría haber sido destruido por Spikepests.",
  ui_story_5026_50260101_66_dialog_content = "Estos tipos corren muy rápido... Oh, ¿viniste aquí a verme por algo?",
  ui_story_5026_50260101_67_dialog_content = "De hecho, vine aquí hoy en nombre de la Sra. Sheol.",
  ui_story_5026_50260101_68_dialog_content = "¿En nombre del Seol?",
  ui_story_5026_50260101_69_dialog_content = "se trata de un <color=#FFB400>factura</color> eso no se ha arreglado.",
  ui_story_5026_50260101_70_dialog_content = "PlayerName, ¿recuerdas tu aventura subterránea en Undercity cerca de Eternal Night?",
  ui_story_5026_50260101_71_dialog_content = "Si estás dispuesto a hacer algo por mí a cambio, estaré encantado de recopilar información sobre Entrañas por ti.",
  ui_story_5026_50260101_72_dialog_content = "Será mejor que vuelvas con vida y pagues.",
  ui_story_5026_50260101_73_dialog_content = "Miss Vice no parece estar cerca. Por lo general, te ayuda a administrar tus gastos, ¿no es así?",
  ui_story_5026_50260101_74_dialog_content = "Pues bien, aquí está la factura. Por favor, eche un vistazo.",
  ui_story_5026_50260101_75_dialog_content = "A ver... ¡¿Eh?! <size=45>¿Este es el precio?</size>",
  ui_story_5026_50260101_76_dialog_content = "Lo sé. Todavía estoy soñando. ¡Debe ser eso! Ajajaja...",
  ui_story_5026_50260101_77_dialog_content = "¿Le gustaría mantenerlo a crédito, PlayerName?",
  ui_story_5026_50260101_78_dialog_content = "Puedo negociar en su nombre, pero se dejará un registro con la Srta. Jane, la Testigo de Umbraton.",
  ui_story_5026_50260101_79_dialog_content = "Esto podría afectar su solvencia en Umbraton, así como el desarrollo a largo plazo de Cloud Gardens.",
  ui_story_5026_50260101_80_dialog_content = "¡Pagaré! ¡Definitivamente pagaré! Simplemente no puedo ahora.",
  ui_story_5026_50260101_81_dialog_content = "Permítame hacerle una pregunta más. ¿Cómo planeas tener en tus manos esta suma de dinero?",
  ui_story_5026_50260101_82_option_content = "¿Montar un puesto en Umbraton y vender mis habilidades psíquicas?",
  ui_story_5026_50260101_83_option_content = "¿Atrapar algunos eclipses corruptos?",
  ui_story_5026_50260101_84_dialog_content = "Un plan de negocios descuidado como ese nunca sería aprobado, PlayerName.",
  ui_story_5026_50260101_85_dialog_content = "Déjame pensar... Cloud Gardens es un lugar bastante agradable.",
  ui_story_5026_50260101_86_dialog_content = "El paisaje es hermoso, hay muchos recursos y puedes encontrar muchas creaciones únicas de Caelestite.",
  ui_story_5026_50260101_87_dialog_content = "¿Cachero?",
  ui_story_5026_50260101_88_dialog_content = "¿Me estás pidiendo que venda Cloud Gardens? ¿O vender Chubbs?",
  ui_story_5026_50260101_89_dialog_content = "Otros comerciantes de Umbraton probablemente propondrían algo similar.",
  ui_story_5026_50260101_90_dialog_content = "Pero esta casa tuya no fue fácil de conseguir, ¿verdad?",
  ui_story_5026_50260101_91_dialog_content = "Lo que quiero decir es que si te esforzaras más en arreglarlo, podría generar una ganancia considerable.",
  ui_story_5026_50260101_92_dialog_content = "Me avergüenza admitirlo, pero han pasado tantas cosas últimamente que apenas he tenido tiempo de ordenar mis pensamientos.",
  ui_story_5026_50260101_93_dialog_content = "Así que no he podido administrar mi nuevo hogar tan bien como me hubiera gustado.",
  ui_story_5026_50260101_94_dialog_content = "Y como acabas de ver, incluso Eclipsites están apareciendo aquí.",
  ui_story_5026_50260101_95_dialog_content = "¡Justo cuando todos se han ido!",
  ui_story_5026_50260101_97_dialog_content = "Por favor, dile a Sheol que estoy agradecido por su ayuda y que no olvidaré el pago que le debo.",
  ui_story_5026_50260101_98_dialog_content = "Entiendo. Solicitaré un período de gracia para usted, PlayerName.",
  ui_story_5026_50260101_99_dialog_content = "¿Tienes un plan para lidiar con esos eclipses?",
  ui_story_5026_50260101_100_dialog_content = "Quién sabe de dónde se arrastraron...",
  ui_story_5026_50260101_100X1_dialog_content = "Pensé que el Acorde de la Ley había purgado a Eraveil de todos los Eclipsites.",
  ui_story_5026_50260101_100X2_dialog_content = "Pero ha pasado un tiempo desde que las cosas fallaron en el Obelisco del Retorno, por lo que tal vez estos Eclipsites deambularon desde otros lugares.",
  ui_story_5026_50260101_100X3_dialog_content = "Bueno, si son solo algunos Spikepests, incluso yo debería poder...",
  ui_story_5026_50260101_101_dialog_content = "Qué tal.",
  ui_story_5026_50260101_102_dialog_content = "¿Qué tal contratar un equipo de gerentes que cumplan con sus expectativas para ayudarlo?",
  ui_story_5026_50260101_103_dialog_content = "Resolvería su problema inmediato de Eclipsite y podría recibir consejos sobre cómo diseñar Cloud Gardens. Dos por el precio de uno.",
  ui_story_5026_50260101_104_dialog_content = "Suena bien, pero ¿cómo haría para encontrar candidatos adecuados?",
  ui_story_5026_50260101_105_dialog_content = "En cuanto al proceso de contratación y los recursos necesarios...",
  ui_story_5026_50260101_106_dialog_content = "Estoy dispuesto a ayudarte con todo eso, PlayerName. Por favor confia en mi.",
  ui_story_5026_50260101_107_dialog_content = "No te preocupes. Estoy ayudando como amigo, así que no es una orden del gremio.",
  ui_story_5026_50260101_108_dialog_content = "Gracias por ser un amigo tan confiable, Bethel...",
  ui_story_5026_50260101_109_dialog_content = "¡Te lo dejo a ti entonces!",
  ui_story_5026_50260201_1_dialog_content = "<color=#e8d9bb>Fuera de Eraveil</color>",
  ui_story_5026_50260201_2_dialog_content = "Bien. Deberíamos estar acercándonos a Cloud Gardens.",
  ui_story_5026_50260201_3_dialog_content = "Eraveil, en su propio rincón aislado del mundo... Incluso Padre no tendría ninguna influencia aquí.",
  ui_story_5026_50260201_4_dialog_content = "Mantenga, <color=#FFB400>Sanae</color>.",
  ui_story_5026_50260201_5_dialog_content = "¡M-Señorita Nina! ¡Espérame!",
  ui_story_5026_50260201_6_dialog_content = "¿No te dije que me llamaras? <color=#FFB400>nina</color> ¿antes de que nos fuéramos? ¡Tienes que llamarme Nina cuando estemos afuera!",
  ui_story_5026_50260201_7_dialog_content = "Prometiste cuando salimos de Umbraton que no nos seguirían, ¿verdad, Sr. Odd Jobs?",
  ui_story_5026_50260201_8_dialog_content = "Me hiere con esas palabras, señorita Andersen. Dependo de la confianza de los clientes para mi sustento.",
  ui_story_5026_50260201_9_dialog_content = "Odd Jobs hará cualquier cosa, desde salvar el mundo hasta buscar gatos, siempre que el cliente lo pida...",
  ui_story_5026_50260201_10_dialog_content = "Bueno, déjame preguntarte esto entonces. ¿Qué esta haciendo él aquí?",
  ui_story_5026_50260201_11_dialog_content = "Argh. Por eso no quería este trabajo...",
  ui_story_5026_50260201_12_dialog_content = "Buenos días, señorita Nina. Ha tenido un largo viaje, así que por favor descanse aquí.",
  ui_story_5026_50260201_13_dialog_content = "... <color=#FFB400>Minos</color>, ¿Cuándo llegaste aquí?",
  ui_story_5026_50260201_14_dialog_content = "Le ruego, señorita, que no acuse injustamente al señor Taki. Realmente no seguí a tu grupo.",
  ui_story_5026_50260201_15_dialog_content = "¡Ay! Una tienda de campaña, una manta de picnic, agua con gas, sándwiches, velas perfumadas e incluso flores frescas...",
  ui_story_5026_50260201_16_dialog_content = "Estás muy bien preparado. Parece que ya habías venido aquí incluso antes de que la señora entrara por la puerta de mi oficina.",
  ui_story_5026_50260201_17_dialog_content = "El mayordomo de élite de los Andersen es realmente algo.",
  ui_story_5026_50260201_18_dialog_content = "Con suficiente información, el itinerario de Miss Nina no es tan difícil de predecir.",
  ui_story_5026_50260201_19_dialog_content = "Por favor, vuelva conmigo después de que termine su té, señorita. El Maestro está preocupado por usted.",
  ui_story_5026_50260201_20_dialog_content = "¡No voy a volver! Estoy huyendo de casa, ¿sabes?",
  ui_story_5026_50260201_21_dialog_content = "Efectivamente, ya tengo mis órdenes. Incluso si tengo que perseguirte hasta el fin del mundo...",
  ui_story_5026_50260201_22_dialog_content = "Debo llevarte a casa.",
  ui_story_5026_50260201_23_dialog_content = "¡Ficticio! ¡El padre es un tonto!",
  ui_story_5026_50260201_24_dialog_content = "Por favor, tenga cuidado con su lenguaje, señorita. Mantenga siempre la elegancia de una dama.",
  ui_story_5026_50260201_25_dialog_content = "Ejem. Parece que no tengo nada más que hacer aquí. Gracias por su patrocinio, señorita Andersen.",
  ui_story_5026_50260201_26_dialog_content = "¡Recuerda dejar una buena reseña cuando regreses a Umbraton!",
  ui_story_5026_50260201_27_dialog_content = "¡Dije, no voy a volver!",
  ui_story_5026_50260201_28_dialog_content = "¡Al menos no hasta que me acerque a Caelestite, me dé cuenta de mis planes y me demuestre a mí mismo! ¡Definitivamente no hasta entonces!",
  ui_story_5026_50260201_29_dialog_content = "U-Um, Sr. Minos, yo...",
  ui_story_5026_50260201_30_dialog_content = "No hay necesidad de que te expliques, Sanae. La prioridad ahora es calmar a nuestra joven señorita y regresar a casa sana y salva.",
  ui_story_5026_50260201_31_dialog_content = "Ha fallado en su deber como sirvienta de la familia Andersen de hacer informes oportunos. Tomaré nota de esto en la evaluación de fin de mes.",
  ui_story_5026_50260201_32_dialog_content = "¿P-Perderé mi trabajo...?",
  ui_story_5026_50260201_33_dialog_content = "¡La estás amenazando!",
  ui_story_5026_50260201_34_dialog_content = "¡Waah! ¡Manae, detente!",
  ui_story_5026_50260201_35_dialog_content = "¿Qué? ¡Solo estoy hablando de hechos!",
  ui_story_5026_50260201_36_dialog_content = "Sé que como la única persona de la misma edad que ella en la mansión, la joven señorita es muy cercana a ti.",
  ui_story_5026_50260201_37_dialog_content = "Esa es probablemente la razón por la que pensó que era necesario traerte en su escapada.",
  ui_story_5026_50260201_38_dialog_content = "Sin embargo, su empleo continuo en la mansión depende de su desempeño esta vez.",
  ui_story_5026_50260201_39_dialog_content = "Q-Qué quieres decir...",
  ui_story_5026_50260201_40_dialog_content = "¡Sanae! ¿Por qué tardas tanto? ¡Vamos a llegar tarde a la entrevista!",
  ui_story_5026_50260201_41_dialog_content = "C-Ya viene!",
  ui_story_5026_50260201_42_dialog_content = "La determinación de la joven señorita es muy impresionante.",
  ui_story_5026_50260201_43_dialog_content = "Entonces yo también tendré que tomar algunas medidas drásticas.",
  ui_story_5026_50260201_44_dialog_content = "<color=#e8d9bb>Cloud Gardens: Área de entrevistas con el gerente</color>",
  ui_story_5026_50260201_45_dialog_content = "...",
  ui_story_5026_50260201_46_dialog_content = "<size=33>Vamos. Di algo, PlayerName.</size>",
  ui_story_5026_50260201_47_dialog_content = "<size=33>¡Así como practicamos!</size>",
  ui_story_5026_50260201_48_dialog_content = "R-Correcto... Primera pregunta: ¿Qué te hizo postularte para ser gerente de Cloud Gardens?",
  ui_story_5026_50260201_49_dialog_content = "Eso es tan aburrido.",
  ui_story_5026_50260201_50_dialog_content = "¿Qué?",
  ui_story_5026_50260201_51_dialog_content = "He cambiado de opinion. Detener la entrevista. Sólo quería echar un vistazo de todos modos.",
  ui_story_5026_50260201_52_dialog_content = "Ven a buscarme de nuevo si necesitas algo para prender fuego.",
  ui_story_5026_50260201_53_dialog_content = "Espero que encuentres un candidato adecuado pronto.",
  ui_story_5026_50260201_54_dialog_content = "Ella se ha ido...",
  ui_story_5026_50260201_55_dialog_content = "No tienes que ser tan cuidadoso, PlayerName. Muestre algo de seriedad como entrevistador.",
  ui_story_5026_50260201_56_dialog_content = "¡Tú gobiernas todo Eraveil!",
  ui_story_5026_50260201_57_dialog_content = "¡Siguiente candidato, por favor!",
  ui_story_5026_50260201_58_dialog_content = "Hola, PlayerName. Soy Connolly.",
  ui_story_5026_50260201_59_dialog_content = "(Gravitas... Soy un gobernante...)",
  ui_story_5026_50260201_60_option_content = "Copia la estabilidad de Schwartz",
  ui_story_5026_50260201_61_dialog_content = "Por favor, tome asiento, señorita Connolly. Es un placer tenerte aquí.",
  ui_story_5026_50260201_62_dialog_content = "Iré directo al grano. Explique su comprensión de Cloud Gardens y del puesto de gerente.",
  ui_story_5026_50260201_63_dialog_content = "¿Tienes estrategias para lidiar con los eclipses? Eres joven, pero ¿tienes alguna sugerencia? Soy todo oídos.",
  ui_story_5026_50260201_64_option_content = "Copia la audacia de Reinhardt",
  ui_story_5026_50260201_65_dialog_content = "¡Jajaja! ¡Ven, Connolly!",
  ui_story_5026_50260201_66_dialog_content = "Si no me equivoco, no tienes ninguna experiencia en el mundo real como gerente, ¿verdad?",
  ui_story_5026_50260201_67_dialog_content = "Perfecto. Aprecio a los que tienen un espíritu de lucha.",
  ui_story_5026_50260201_68_dialog_content = "Mientras estés dispuesto a trabajar duro, esto no será un problema. ¡Te haré un excelente \"soldado\"!",
  ui_story_5026_50260201_69_option_content = "Copia la genialidad de Belén",
  ui_story_5026_50260201_70_dialog_content = "Toma asiento. Fue la mano del destino la que trajo tu llegada sobre nosotros.",
  ui_story_5026_50260201_71_dialog_content = "Pareces un poco nervioso. ¿Quieres una taza de té negro?",
  ui_story_5026_50260201_72_dialog_content = "Uh... ¡El Sr. Navigator está actuando muy extraño hoy!",
  ui_story_5026_50260201_73_dialog_content = "¡Lo siento! ¡No estaba tratando de ser difícil!",
  ui_story_5026_50260201_74_dialog_content = "Pobre de mí. Me equivoqué de nuevo.",
  ui_story_5026_50260201_75_dialog_content = "Se está haciendo tarde. ¿Cuántos candidatos más quedan?",
  ui_story_5026_50260201_76_dialog_content = "Aquí están los currículos restantes. Déjame ver...",
  ui_story_5026_50260201_77_dialog_content = "¡G-Graah!",
  ui_story_5026_50260201_78_dialog_content = "¿Ese es un candidato? Parece bastante inusual.",
  ui_story_5026_50260201_79_dialog_content = "(Eclipsian) ¡Haré cualquier cosa! ¡Por favor solo dame el trabajo!",
  ui_story_5026_50260201_80_dialog_content = "¡¿Cómo entró un Eclipsite?!",
  ui_story_5026_50260201_81_dialog_content = "¡Y hay más de uno!",
  ui_story_5026_50260202_1_dialog_content = "No esperaba que los Eclipsites entraran a tientas en el área de reclutamiento...",
  ui_story_5026_50260202_2_dialog_content = "El problema de Eclipsite en Cloud Gardens es más serio de lo que pensaba.",
  ui_story_5026_50260202_3_dialog_content = "Aunque necesito urgentemente un ayudante, creo que hemos terminado con las entrevistas por hoy.",
  ui_story_5026_50260202_4_dialog_content = "Lo siento mucho... Te prometí que te ayudaría.",
  ui_story_5026_50260202_5_dialog_content = "No, no, todo depende de mí.",
  ui_story_5026_50260202_6_dialog_content = "Necesito contratar a alguien, pero el salario que puedo ofrecer no alcanza ni para comprar una réplica de la pintura.",
  ui_story_5026_50260202_7_dialog_content = "Aunque tengo muchos amigos en Umbraton...",
  ui_story_5026_50260202_8_dialog_content = "No puedo seguir confiando en su buena voluntad. Deberían ser pagados por su arduo trabajo.",
  ui_story_5026_50260202_9_dialog_content = "Pero si las cosas siguen así...",
  ui_story_5026_50260202_10_dialog_content = "Creo que esta es la primera vez que nos vemos, Sr. Navegante.",
  ui_story_5026_50260202_11_dialog_content = "Wow, así que este es el rumoreado Jardín de las Nubes...",
  ui_story_5026_50260202_12_dialog_content = "Es bastante diferente de lo que Umbraton Daily describió en la serie: \"¡Revelado! ¡El enigmático último Caelestite!\"",
  ui_story_5026_50260202_13_dialog_content = "¿Hay más candidatos...?",
  ui_story_5026_50260202_14_dialog_content = "H-Hola. Déjame echar un vistazo a tu currículum... Debes ser Nina.",
  ui_story_5026_50260202_15_dialog_content = "Graduado de Dawn Academy con amplia experiencia en desarrollo empresarial y gestión de recursos humanos...",
  ui_story_5026_50260202_16_dialog_content = "¡Es Correcto!",
  ui_story_5026_50260202_17_dialog_content = "¿Y su pareja Sanae puede encargarse de la limpieza de la casa, la jardinería y varios trabajos de lavado?",
  ui_story_5026_50260202_18_dialog_content = "¡Haré lo mejor que pueda!",
  ui_story_5026_50260202_19_dialog_content = "¡Parecen los mejores candidatos hasta ahora!",
  ui_story_5026_50260202_20_dialog_content = "Excelente, PlayerName.",
  ui_story_5026_50260202_21_dialog_content = "¿Estás listo para alcanzar la cima de tu vida con mi ayuda?",
  ui_story_5026_50260202_22_dialog_content = "¿Eh?",
  ui_story_5026_50260202_23_dialog_content = "¡Haré a la medida un plan de dominación para el último Caelestite en el continente!",
  ui_story_5026_50260202_24_dialog_content = "¡¿Dominación?! Eso es un poco dramático...",
  ui_story_5026_50260202_25_dialog_content = "Sería una situación de ganar-ganar para los dos. Creo que tomarás la decisión correcta.",
  ui_story_5026_50260202_26_dialog_content = "O-Está bien. Por favor, dame un minuto.",
  ui_story_5026_50260202_27_dialog_content = "El currículum solo incluye la información de dos personas, entonces, ¿quién podrías ser?",
  ui_story_5026_50260202_28_dialog_content = "Saludos. Por favor, perdone mi intrusión. Puedes llamarme Minos.",
  ui_story_5026_50260202_29_dialog_content = "Fui entrenado en la Escuela de Entrenamiento de Mayordomo en Lumopolis. Aquí están mi certificado y licencia.",
  ui_story_5026_50260202_30_dialog_content = "¡Vaya, muy profesional! ¿Ustedes tres son un equipo?",
  ui_story_5026_50260202_31_dialog_content = "¡Claro que no!",
  ui_story_5026_50260202_32_dialog_content = "¿Qué?",
  ui_story_5026_50260202_33_dialog_content = "Miss Nina y yo tenemos un pequeño malentendido. Por favor, no te preocupes. Yo me encargare.",
  ui_story_5026_50260202_34_dialog_content = "Si no me equivoco, debe estar bastante satisfecho con nuestros currículos, ¿correcto?",
  ui_story_5026_50260202_35_dialog_content = "Si...",
  ui_story_5026_50260202_36_dialog_content = "Me siento honrado de haber sido seleccionado donde todos los demás han fallado.",
  ui_story_5026_50260202_37_dialog_content = "Bueno, sobre eso... En realidad...",
  ui_story_5026_50260202_38_dialog_content = "Debe tener requisitos muy estrictos para su gerente. La selección final te preocupa.",
  ui_story_5026_50260202_39_dialog_content = "Dejando a un lado los requisitos, es más el hecho de que el mejor salario que puedo ofrecerle es bastante...",
  ui_story_5026_50260202_40_dialog_content = "Tengo una propuesta.",
  ui_story_5026_50260202_41_dialog_content = "¿Qué hay de las dos damas y yo? <color=#FFB400>dividir en dos grupos</color> y servirte como <color=#FFB400>gerentes de prueba</color> ¿sin pagar?",
  ui_story_5026_50260202_42_dialog_content = "¿Gratis?",
  ui_story_5026_50260202_43_dialog_content = "Eso es correcto. Actuaremos simultáneamente como sus gerentes y, al final, contratará al grupo más competente.",
  ui_story_5026_50260202_44_dialog_content = "Su satisfacción es lo primero. El pago se puede negociar después del período de prueba.",
  ui_story_5026_50260202_45_dialog_content = "Este es un método común para las ofertas comerciales en Umbraton, espero que pueda resolver sus inquietudes.",
  ui_story_5026_50260202_46_dialog_content = "¡Gratis!",
  ui_story_5026_50260202_47_dialog_content = "Señorita Nina, Sanae, pido disculpas por tomarme la libertad de presentar esta propuesta. Si hay alguna objeción—",
  ui_story_5026_50260202_48_dialog_content = "¡Bien, vamos a competir!",
  ui_story_5026_50260202_49_dialog_content = "No me importa la paga, porque el potencial de Eraveil no es algo que se pueda definir monetariamente. ¿No lo crees?",
  ui_story_5026_50260202_50_dialog_content = "Supongo que sí.",
  ui_story_5026_50260202_51_dialog_content = "En cualquier caso, obtener tres ayudantes muy capaces de forma gratuita es más de lo que podría haber esperado.",
  ui_story_5026_50260202_52_dialog_content = "Betel, ¿cuál es tu opinión?",
  ui_story_5026_50260202_53_dialog_content = "...",
  ui_story_5026_50260202_54_dialog_content = "¡Excelente! ¡Parece que podemos terminar las entrevistas entonces!",
  ui_story_5026_50260202_55_dialog_content = "¿Eh? ¡Derecha!",
  ui_story_5026_50260202_56_dialog_content = "Pues bien, Minos, Nina y Sanae... ¡Cuento con ustedes para administrar Cloud Gardens!",
  ui_story_5026_50260202_57_dialog_content = "Es un poco tarde, pero... Bienvenido a Cloud Gardens. ¡Espero que te guste aquí!",
  ui_story_5026_50260202_58_dialog_content = "Nina, Nina Andersen...",
  ui_story_5026_50260202_59_dialog_content = "La joven señorita de la familia Andersen. ¿Por qué oculta su apellido y solicita el puesto de gerente en Cloud Gardens?",
  ui_story_5026_50260202_60_dialog_content = "Y Sanae es una sirvienta a quien presenté a la familia Andersen recientemente.",
  ui_story_5026_50260202_61_dialog_content = "En cuanto a Minos, es un verdadero mayordomo.",
  ui_story_5026_50260202_62_dialog_content = "Siempre estaba siguiendo al Conde Andersen como una sombra cada vez que visitaba su mansión por negocios.",
  ui_story_5026_50260202_63_dialog_content = "Que extraño grupo.",
  ui_story_5026_50260202_64_dialog_content = "Pero la familia Andersen es amiga de mi padre. También escuché que Nina era una niña seria cuando estaba en la Academia Dawn...",
  ui_story_5026_50260202_65_dialog_content = "De todos modos, todavía queda trabajo por hacer, así que tengo que volver a Umbraton.",
  ui_story_5026_50260202_66_dialog_content = "No debería haber nada de qué preocuparse...",
  ui_story_5026_50260301_1_dialog_content = "<color=#e8d9bb>Jardines de nubes: fuente de esperanza</color>",
  ui_story_5026_50260301_2_dialog_content = "Fue un aviso de reclutamiento publicado por Cloudrover Guild lo que me trajo aquí, pero no esperaba que Bethel fuera el que estaba detrás.",
  ui_story_5026_50260301_3_dialog_content = "¿Ya ha establecido una relación comercial con Caelestite? Nada menos de un estudiante superior.",
  ui_story_5026_50260301_4_dialog_content = "Y Minos, ¿qué diablos estás tramando?",
  ui_story_5026_50260301_5_dialog_content = "Por favor, tenga cuidado con su lenguaje, señorita. Mantenga siempre la elegancia de una dama.",
  ui_story_5026_50260301_6_dialog_content = "Era simplemente una propuesta, como te describí y PlayerName.",
  ui_story_5026_50260301_7_dialog_content = "¿Solo para evitar que me quede aquí? ¿Crees que me iré a casa obedientemente de esa manera?",
  ui_story_5026_50260301_8_dialog_content = "Habría pensado que alguien en quien papá confía tanto habría ideado algo más inteligente.",
  ui_story_5026_50260301_9_dialog_content = "Me da demasiado crédito, señorita. Es un honor para mí recibir la Maestría y su reconocimiento.",
  ui_story_5026_50260301_10_dialog_content = "¡No te estaba alabando!",
  ui_story_5026_50260301_11_dialog_content = "Déjame ser claro: ¡no perderé!",
  ui_story_5026_50260301_12_dialog_content = "Tengo tantas tiendas en Umbraton: tiendas de ropa, joyerías, tiendas de armas...",
  ui_story_5026_50260301_13_dialog_content = "Una simple finca no es nada para mí.",
  ui_story_5026_50260301_14_dialog_content = "Administrar un lugar como este es tan fácil como un pastel.",
  ui_story_5026_50260301_15_dialog_content = "De todos modos, después de ganarme la confianza de Caelestite...",
  ui_story_5026_50260301_16_dialog_content = "¡Convertiré este lugar en una metrópolis comercial que no sea inferior a Umbraton de ninguna manera, paso a paso!",
  ui_story_5026_50260301_17_dialog_content = "Un día, este lugar irá más lejos que esa ciudad muerta que respira a la sombra de Lumopolis.",
  ui_story_5026_50260301_18_dialog_content = "Te haré saber a ti y a papá que incluso sin la riqueza y la influencia de la familia Andersen...",
  ui_story_5026_50260301_19_dialog_content = "¡Todavía puedo hacer algo por mí mismo!",
  ui_story_5026_50260301_20_dialog_content = "Por supuesto, señorita. Su gran visión es admirable.",
  ui_story_5026_50260301_21_dialog_content = "Por favor, permítame hacer una propuesta más entonces.",
  ui_story_5026_50260301_22_dialog_content = "Si puedes vencerme <color=#FFB400>cualquier cosa</color> cuando trabaje en Cloud Gardens, dejaré de traerte a casa.",
  ui_story_5026_50260301_23_dialog_content = "Sigue adelante.",
  ui_story_5026_50260301_24_dialog_content = "Si ganas, me iré inmediatamente. No nos volveremos a ver a menos que tú lo desees.",
  ui_story_5026_50260301_25_dialog_content = "¿Lo prometes?",
  ui_story_5026_50260301_26_dialog_content = "Prometo. Además, puedes conseguir algunos ayudantes. Lo recomiendo.",
  ui_story_5026_50260301_27_dialog_content = "Pero es difícil decir cuánto te ayudará Sanae. Después de todo, rompió más tazas de té de las que lavó en la mansión.",
  ui_story_5026_50260301_28_dialog_content = "¡Tú!",
  ui_story_5026_50260301_29_dialog_content = "M-Señorita! ¡Quiero decir, Nina! PlayerName es aquí.",
  ui_story_5026_50260301_30_dialog_content = "Perdón por llegar tarde. Me tomó algún tiempo limpiar el área de la entrevista.",
  ui_story_5026_50260301_31_dialog_content = "¿Pasó algo?",
  ui_story_5026_50260301_32_dialog_content = "(Me pareció ver a Nina tratando de golpear a Minos en la cabeza con su paraguas... Eso es un paraguas, ¿verdad?)",
  ui_story_5026_50260301_33_dialog_content = "¡Nada en absoluto!",
  ui_story_5026_50260301_34_dialog_content = "No hay necesidad de preocuparse por eso, Sr. Navegante. Por favor adelante.",
  ui_story_5026_50260301_35_dialog_content = "Ejem, entonces, como escribí en la descripción del trabajo...",
  ui_story_5026_50260301_36_dialog_content = "Espero que se unan a mí para patrullar toda el área, evaluar la gravedad de la invasión de Eclipsites y eliminar Eclipsites.",
  ui_story_5026_50260301_37_dialog_content = "Además, me gustaría que experimentaras las tareas diarias de Cloud Gardens y me hicieras sugerencias sobre cómo generar ingresos como profesionales.",
  ui_story_5026_50260301_38_dialog_content = "(Bethel escribió la descripción para mí, ¡y la redacción es tan formal! No estoy muy acostumbrado...)",
  ui_story_5026_50260301_39_dialog_content = "E-Entonces... Te daré una breve introducción antes de que empecemos a trabajar.",
  ui_story_5026_50260301_40_dialog_content = "Esta es el área central de Cloud Gardens.",
  ui_story_5026_50260301_41_dialog_content = "No importa dónde quiera visitar, este es el lugar inteligente más conveniente.",
  ui_story_5026_50260301_42_dialog_content = "La torre blanca detrás de nosotros se llama la Torre Jacinto.",
  ui_story_5026_50260301_43_dialog_content = "Todas estas torres blancas, incluida la Torre Jacinto, son complejos dejados por los antiguos caelestitas.",
  ui_story_5026_50260301_44_dialog_content = "También hay muchos planos apilados en las torres, así como algunos dispositivos que no pude activar...",
  ui_story_5026_50260301_45_dialog_content = "¿Vaya? ¿Invenciones de Caelestites quizás? ¿Tienes planos de armas?",
  ui_story_5026_50260301_46_dialog_content = "Uh... Hasta ahora solo he descubierto planos de edificios y muebles.",
  ui_story_5026_50260301_47_dialog_content = "PlayerName, eres el único Caelestite conocido hasta ahora.",
  ui_story_5026_50260301_48_dialog_content = "Posees una aeronave gigante y tecnología antigua misteriosa, además puedes mejorar aurorianos para la batalla.",
  ui_story_5026_50260301_49_dialog_content = "Dicen que los Caelestitas siempre fueron amables y pacíficos...",
  ui_story_5026_50260301_50_dialog_content = "Pero su sueño no se detiene en la remodelación de Eraveil, ¿verdad?",
  ui_story_5026_50260301_51_dialog_content = "(¡Nina parece haber investigado un poco sobre mí!)",
  ui_story_5026_50260301_52_dialog_content = "Pareces sorprendido.",
  ui_story_5026_50260301_53_dialog_content = "Usted es un socio comercial importante, por lo que una verificación de antecedentes era esencial.",
  ui_story_5026_50260301_54_dialog_content = "Dicho esto, ¿estás interesado en mi plan de dominación ahora?",
  ui_story_5026_50260301_55_dialog_content = "Bueno, hasta ahora realmente ni siquiera he arreglado las cosas en Eraveil todavía...",
  ui_story_5026_50260301_56_dialog_content = "La prioridad ahora es centrarse en las tareas que tenemos por delante.",
  ui_story_5026_50260301_57_dialog_content = "Si no hay más preguntas...",
  ui_story_5026_50260301_58_dialog_content = "¿Por qué no empezamos plantando árboles?",
  ui_story_5026_50260301_59_dialog_content = "Así que aquí es donde cultivas árboles únicos...",
  ui_story_5026_50260301_60_dialog_content = "... O bueno, cualquier cosa.",
  ui_story_5026_50260301_61_dialog_content = "¿Quizás su cualidad única es que pueden volverse invisibles?",
  ui_story_5026_50260301_62_dialog_content = "De hecho, el aislado Eraveil tiene especies de plantas muy singulares.",
  ui_story_5026_50260301_63_dialog_content = "Tengo que admitir que nunca antes había cultivado plantas. Entonces, como puedes ver...",
  ui_story_5026_50260301_64_dialog_content = "¿La mayor parte de lo que se plantó no germinó, y los que crecieron quedaron torcidos?",
  ui_story_5026_50260301_65_dialog_content = "Ah, sí. Pero no tengo intención de rendirme.",
  ui_story_5026_50260301_66_dialog_content = "Recortémoslos y plantemos nuevas semillas.",
  ui_story_5026_50260301_67_dialog_content = "Suena como un trabajo que ensuciaría las faldas...",
  ui_story_5026_50260301_68_dialog_content = "¿Qué es eso que parece una cuchara gigante?",
  ui_story_5026_50260301_69_dialog_content = "Es una pala, para palear tierra. ¿Nunca has visto uno antes?",
  ui_story_5026_50260301_70_dialog_content = "¡Claro que tengo! ¡Lo he visto muchas veces en mis visitas a la granja con mi padre!",
  ui_story_5026_50260301_71_dialog_content = "¡Este se ve diferente de los que usa mi familia!",
  ui_story_5026_50260301_72_dialog_content = "Sólo... ¡Solo dámelo y déjame echarle un buen vistazo!",
  ui_story_5026_50260301_73_dialog_content = "¿Hay tantos tipos de palas? Plantar cosas es mucho más complicado de lo que pensaba.",
  ui_story_5026_50260301_74_dialog_content = "Déjame ir a ver qué están haciendo los otros dos.",
  ui_story_5026_50260301_75_dialog_content = "Hola, PlayerName.",
  ui_story_5026_50260301_76_dialog_content = "Sobre la poda del Árbol Único... ¿preferirías el estilo de Lumopolis, o el del Palacio de Invierno de Northland?",
  ui_story_5026_50260301_77_dialog_content = "Ambos son populares en Umbraton, pero nuestro Last Caelestite puede tener gustos diferentes.",
  ui_story_5026_50260301_78_dialog_content = "Por favor perdoname. Me adelanté.",
  ui_story_5026_50260301_79_dialog_content = "... Esto es tan extra!",
  ui_story_5026_50260301_80_dialog_content = "<size=37>Me pregunto cómo sabría la fruta de un árbol único.</size>",
  ui_story_5026_50260301_81_dialog_content = "<size=35>¿Obtendría algún poder especial al comerlo? ¿Me crecerían alas y una cola?</size>",
  ui_story_5026_50260301_82_dialog_content = "<size=33>Este es el jardín de ese Enigmático Último Caelestite después de todo...</size>",
  ui_story_5026_50260301_83_dialog_content = "<size=40>¡Ah! ¡Este no es el momento para reflexionar sobre estas cosas! Si no ayudo al Sr. Minos, voy a...</size>",
  ui_story_5026_50260301_84_dialog_content = "<size=33>Pero tampoco quiero hacer algo que entristecerá a la señorita Nina...</size>",
  ui_story_5026_50260301_85_dialog_content = "(Sanae parece estar mirando el hoyo frente a ella y murmurando para sí misma...)",
  ui_story_5026_50260301_86_dialog_content = "Eh, Sanae...",
  ui_story_5026_50260301_87_dialog_content = "¡Sí! ¡Ese soy yo!",
  ui_story_5026_50260301_88_dialog_content = "Solo necesitamos algunos agujeros poco profundos para enterrar las semillas. El hoyo que cavaste es lo suficientemente profundo como para enterrarme.",
  ui_story_5026_50260301_89_dialog_content = "¡Acabo de hacer algunas excavaciones ligeras!",
  ui_story_5026_50260301_90_dialog_content = "Cachero...",
  ui_story_5026_50260301_91_dialog_content = "¡Caelestita detectada, Chubb!",
  ui_story_5026_50260301_92_dialog_content = "¿Qué es ese sonido?",
  ui_story_5026_50260301_93_dialog_content = "Esta pala gruesa es realmente impresionante, PlayerName.",
  ui_story_5026_50260301_94_dialog_content = "Simplemente enterramos las semillas del árbol y golpeamos la tierra con la pala dos veces...",
  ui_story_5026_50260301_95_dialog_content = "Y aquí tenemos un Árbol Único parlante ante nosotros en un abrir y cerrar de ojos.",
  ui_story_5026_50260301_96_dialog_content = "Oh, esto no es un árbol único. Probablemente pasó a caminar sobre este montón.",
  ui_story_5026_50260301_97_dialog_content = "¡Yo... yo sabía totalmente que ese era el caso! ¿Cómo podría ser un Árbol Único?",
  ui_story_5026_50260301_98_dialog_content = "Los llamamos Chubbs. Aparecieron con Cloud Gardens después de que se levantara el Obelisco del Retorno.",
  ui_story_5026_50260301_99_dialog_content = "¡Cachero!",
  ui_story_5026_50260301_100_dialog_content = "Está...",
  ui_story_5026_50260301_101_dialog_content = "Es tan lindo...!",
  ui_story_5026_50260301_102_dialog_content = "Ejem, quiero decir, ¿qué puede hacer este pequeño?",
  ui_story_5026_50260301_103_dialog_content = "Por lo que has descrito, es un residente de Cloud Gardens, como tú.",
  ui_story_5026_50260301_104_dialog_content = "Entonces, además de ser lindo, debería contribuir con algo a este lugar, ¿verdad?",
  ui_story_5026_50260301_105_dialog_content = "Cachero...",
  ui_story_5026_50260301_106_dialog_content = "Algunos Chubbs me enseñan cosas sobre Cloud Gardens y me ayudan a cuidar los Unique Trees.",
  ui_story_5026_50260301_107_dialog_content = "Pero la mayoría de los Chubbs simplemente caminan o se quedan dormidos aquí.",
  ui_story_5026_50260301_108_dialog_content = "Tampoco sé mucho sobre los detalles de su estructura o función.",
  ui_story_5026_50260301_109_dialog_content = "Pero solo verlos caminar me hace feliz.",
  ui_story_5026_50260301_110_dialog_content = "Bueno, a algunos de los chicos de Rediesel Wrench e Illumina les gusta perseguirlos, diciendo cosas sobre desmontarlos para echar un vistazo...",
  ui_story_5026_50260301_111_dialog_content = "¡Cachero! ¡Sin desarmar a Chubb!",
  ui_story_5026_50260301_112_dialog_content = "Es tímido, como un conejo.",
  ui_story_5026_50260301_113_dialog_content = "Uh... Solo acaricio a este pequeño porque parece asustado. No es como si quisiera acariciarlo ni nada. No me malinterpretes.",
  ui_story_5026_50260301_114_dialog_content = "(Han aparecido eclipses en Cloud Gardens, pero estos Chubbs todavía están relajados).",
  ui_story_5026_50260301_115_dialog_content = "(¿Es porque son tontos o, como los antiguos Caelestitas, simplemente no ven a los Eclipsitas como enemigos?)",
  ui_story_5026_50260301_116_dialog_content = "(Las reliquias de hace eones contienen tantos secretos, y no estoy seguro de querer saberlos todos...)",
  ui_story_5026_50260301_117_dialog_content = "¿Cachero?",
  ui_story_5026_50260301_118_dialog_content = "(Debe ser porque tienen la cabeza hueca).",
  ui_story_5026_50260301_119_dialog_content = "¡Cachero!",
  ui_story_5026_50260301_120_dialog_content = "¿Otro? ¿Quieres que te rasque la oreja también? Bueno, no puedo decir que no a eso.",
  ui_story_5026_50260301_121_dialog_content = "Entonces, si este se llama Chubb, ¿qué pasa con el otro?",
  ui_story_5026_50260301_122_dialog_content = "¿Eh? También se llama Chubb.",
  ui_story_5026_50260301_123_dialog_content = "Pero se ven diferentes. ¡Mira la forma de sus ojos y la curva de sus bocas cuando sonríen!",
  ui_story_5026_50260301_124_dialog_content = "¿Hay alguna diferencia?",
  ui_story_5026_50260301_125_dialog_content = "Que aficionado...",
  ui_story_5026_50260301_126_dialog_content = "¿Aficionado?",
  ui_story_5026_50260301_127_dialog_content = "Escuchen, PlayerName.",
  ui_story_5026_50260301_128_dialog_content = "Uno de los principios fundamentales de la gestión es conocer bien a sus empleados.",
  ui_story_5026_50260301_129_dialog_content = "He tenido la intención de preguntarle esto desde antes... ¿Dónde está su lista de personal, sus libros de cuentas y su libro de registro de bienes?",
  ui_story_5026_50260301_130_dialog_content = "¿Qué son todos esos?",
  ui_story_5026_50260301_131_dialog_content = "¿Ni siquiera sabes lo que es una lista de personal?",
  ui_story_5026_50260301_132_dialog_content = "Siento que estaría insultando tu inteligencia si te diera una explicación, pero puedo empezar desde lo básico.",
  ui_story_5026_50260301_133_dialog_content = "Espera, creo que siento algo cerca... Eso es—",
  ui_story_5026_50260301_134_dialog_content = "¡Waaaaah!",
  ui_story_5026_50260301_135_dialog_content = "¡¿N-Ahora qué?!",
  ui_story_5026_50260301_136_dialog_content = "<anim type=Shake>Graagh!</anim>",
  ui_story_5026_50260301_137_dialog_content = "Acabo de pinchar un poco los arbustos...",
  ui_story_5026_50260301_138_dialog_content = "¿Cómo defines exactamente \"un poco\"?",
  ui_story_5026_50260402_1_dialog_content = "<anim type=Shake>Gaah...</anim>",
  ui_story_5026_50260402_2_dialog_content = "Hmph. Fácil.",
  ui_story_5026_50260402_3_dialog_content = "sanae, PlayerName, ¿estás bien?",
  ui_story_5026_50260402_4_dialog_content = "E-simplemente saltaron de los arbustos de repente y me asustaron.",
  ui_story_5026_50260402_5_dialog_content = "Esto es una sorpresa. Nina, en realidad eres hábil en el combate.",
  ui_story_5026_50260402_6_dialog_content = "Hmph, al menos puedes decirlo.",
  ui_story_5026_50260402_7_dialog_content = "Tu habilidad psíquica también es muy especial, permitiéndote ver estelas de luz. Me ha dado una nueva inspiración de diseño.",
  ui_story_5026_50260402_8_dialog_content = "Espera un segundo... ¿Qué quisiste decir con \"sorpresa\"? ¿Me estás subestimando?",
  ui_story_5026_50260402_9_dialog_content = "Porque no pareces alguien que pasa mucho tiempo blandiendo armas...",
  ui_story_5026_50260402_10_dialog_content = "Pero usted está en lo correcto. Lo siento, no debería haber hecho suposiciones sobre ti basándome en las primeras impresiones.",
  ui_story_5026_50260402_11_dialog_content = "Gracias a ti, nos hemos deshecho de los enemigos y esta área ahora está completamente libre de Darkflow.",
  ui_story_5026_50260402_12_dialog_content = "Gracias, Nina.",
  ui_story_5026_50260402_13_dialog_content = "N-No hay necesidad de ser tan formal, y...",
  ui_story_5026_50260402_14_dialog_content = "¡Y tampoco hace falta que te acerques tanto!",
  ui_story_5026_50260402_15_dialog_content = "(¡Tú eres el que se acercó!)",
  ui_story_5026_50260402_16_dialog_content = "<size=33>Él es a quien el tío Istvan ha estado vigilando de cerca... No puedo bajar la guardia.</size>",
  ui_story_5026_50260402_17_dialog_content = "Y tienes razón. Como dama...",
  ui_story_5026_50260402_18_dialog_content = "... ¿Qué dicen de nuevo? Oh, como dama, debería ser \"más elegante y digna\" y no debería \"andar con armas\".",
  ui_story_5026_50260402_19_dialog_content = "Sin mencionar que prefiero fabricar armas que empuñarlas.",
  ui_story_5026_50260402_20_dialog_content = "Quién sabe qué dirían esas mujeres nobles críticas si se enteraran de esto.",
  ui_story_5026_50260402_21_dialog_content = "¿Mujeres nobles?",
  ui_story_5026_50260402_22_dialog_content = "¡N-Nada! Eliminar eclipses es parte de mi trabajo, ¡solo estaba siendo un buen empleado!",
  ui_story_5026_50260402_23_dialog_content = "Además, este es solo el primer paso para arreglar Cloud Gardens, ¡siéntate y mírame trabajar en todo mi esplendor!",
  ui_story_5026_50260402_24_dialog_content = "Oh, hablando de eso.",
  ui_story_5026_50260402_25_dialog_content = "Minos parece haber terminado todo el trabajo de plantación mientras hablábamos de las diferencias de Chubb.",
  ui_story_5026_50260402_26_dialog_content = "¿Eh?",
  ui_story_5026_50260402_27_dialog_content = "Aflojó la tierra, sembró las semillas, las regó y las fertilizó...",
  ui_story_5026_50260402_28_dialog_content = "También colocó señales de marcador para cada parcela de tierra y las rodeó con flores que complementan el color de los árboles.",
  ui_story_5026_50260402_29_dialog_content = "¡Chubb también lo ve, Chubb!",
  ui_story_5026_50260402_30_dialog_content = "¡Increíble, Chubb!",
  ui_story_5026_50260402_31_dialog_content = "Me halagas, Sr. Navegante... y querido pequeño Chubbs.",
  ui_story_5026_50260402_32_dialog_content = "Permítame recordarle, Maestro de Cloud Gardens, que es demasiado pronto para sentirse seguro sobre el problema de Eclipsite.",
  ui_story_5026_50260402_33_dialog_content = "Acabo de ver una sombra oscura que sospeché que era un Eclipsite corriendo hacia esos edificios en la distancia.",
  ui_story_5026_50260402_34_dialog_content = "Seguiré adelante e investigaré, solo para estar seguro. Por favor Disculpame.",
  ui_story_5026_50260402_35_dialog_content = "¡Vaya, se fue tan rápido!",
  ui_story_5026_50260402_36_dialog_content = "Acabo de perder una ronda. No puedo volver a atrasarme.",
  ui_story_5026_50260402_37_dialog_content = "¡Sanae, vamos!",
  ui_story_5026_50260402_38_dialog_content = "¿Realmente tenemos una oportunidad contra el Sr. Minos...?",
  ui_story_5026_50260402_39_dialog_content = "Parece que están más preocupados por la seguridad de Cloud Gardens que yo...",
  ui_story_5026_50260402_40_dialog_content = "¿Es esta la dedicación del contrato por la que son conocidos los Umbratons?",
  ui_story_5026_50260501_1_dialog_content = "¿Qué es esto? ¡No hay Eclipsite en ninguna parte!",
  ui_story_5026_50260501_2_dialog_content = "¿Minos ya se ocupó de eso?",
  ui_story_5026_50260501_3_dialog_content = "Yo tampoco siento ningún Darkflow. Aún así, no debemos bajar la guardia.",
  ui_story_5026_50260501_4_dialog_content = "Este gran claro frente a nosotros debería ser seguro, al menos.",
  ui_story_5026_50260501_5_dialog_content = "Este lugar parece un poco familiar...",
  ui_story_5026_50260501_6_dialog_content = "Obviamente. No importa en qué dirección mires aquí, es solo el mismo campo de hierba que se extiende hacia afuera.",
  ui_story_5026_50260501_7_dialog_content = "¡Correcto! ¡Fui a una búsqueda del tesoro cerca de aquí antes, con Vice!",
  ui_story_5026_50260501_8_dialog_content = "He oído que la gente de las zonas rurales utiliza estos métodos para atraer aventureros que sueñan con riquezas fáciles.",
  ui_story_5026_50260501_9_dialog_content = "No es una mala manera de estimular la economía local, pero...",
  ui_story_5026_50260501_10_dialog_content = "Esto parece un campo vacío. ¿De verdad puedes encontrar un tesoro aquí?",
  ui_story_5026_50260501_11_dialog_content = "Eh, bueno.",
  ui_story_5026_50260501_12_dialog_content = "<size=45>¡Waaaah!</size>",
  ui_story_5026_50260501_13_dialog_content = "¡¿Eh?!",
  ui_story_5026_50260501_14_dialog_content = "¿Qué me hizo tropezar... una piedra?",
  ui_story_5026_50260501_15_dialog_content = "tesoro encontrado! ¡Cachero!",
  ui_story_5026_50260501_16_dialog_content = "Waah, estoy tan mareado... El Chubb parece haberse multiplicado...",
  ui_story_5026_50260501_17_dialog_content = "¡Realmente hay muchos Chubbs, Chubb!",
  ui_story_5026_50260501_18_dialog_content = "¡Ay, ay, vete! ¡Cachero!",
  ui_story_5026_50260501_19_dialog_content = "Estoy aplastado, Chubb...",
  ui_story_5026_50260501_20_dialog_content = "Sanae siempre parece meterse en situaciones. ¿Debo considerar eso desafortunado, o afortunado...?",
  ui_story_5026_50260501_21_dialog_content = "nina? ¿Qué es? ¿Te gustaría cavar también?",
  ui_story_5026_50260501_22_dialog_content = "Realmente no quiero.",
  ui_story_5026_50260501_23_dialog_content = "Mi vestido se manchará porque hay mucha suciedad. Este vestido es mi último trabajo...",
  ui_story_5026_50260501_24_dialog_content = "(Ella sigue mirando la herramienta en mi mano...)",
  ui_story_5026_50260501_25_dialog_content = "Deberías darle una oportunidad. Toma, puedes tomar prestado esto.",
  ui_story_5026_50260501_26_dialog_content = "Um... Ya que insistes, y esto es parte de los deberes diarios de Cloud Gardens, lo intentaré.",
  ui_story_5026_50260501_27_dialog_content = "Pero es posible que deba moverse más rápido.",
  ui_story_5026_50260501_28_dialog_content = "Mira allí. De alguna manera, Minos ya tiene un alijo apilado a sus pies.",
  ui_story_5026_50260501_29_dialog_content = "Incluso los Chubb parecen impresionados.",
  ui_story_5026_50260501_30_dialog_content = "(¿Eh? Espera...)",
  ui_story_5026_50260501_31_dialog_content = "(¿Han saltado estos muchachos a mi alrededor con tanto entusiasmo y felicidad antes?)",
  ui_story_5026_50260501_32_dialog_content = "Ya lo sabía, pero realmente es bueno en todo... ¡Es tan injusto!",
  ui_story_5026_50260501_33_dialog_content = "Sí, me pregunto cómo lo hizo. Estaba tan concentrada en ver a Sanae que no presté atención a lo que estaba haciendo...",
  ui_story_5026_50260501_34_dialog_content = "Oye, ¿no tienes mejores herramientas para buscar tesoros?",
  ui_story_5026_50260501_35_dialog_content = "Hay algunas otras herramientas al lado del molino de viento allí.",
  ui_story_5026_50260501_36_dialog_content = "Espera, creo que están en el almacén al lado del molino de viento... pero ese lugar no ha sido limpiado en mucho tiempo.",
  ui_story_5026_50260501_37_dialog_content = "Tsk. Esto no funcionará.",
  ui_story_5026_50260501_38_dialog_content = "Como maestro de Cloud Gardens, ¡debes conocer tu propiedad como la palma de tu mano!",
  ui_story_5026_50260501_39_dialog_content = "De todos modos, iré a echar un vistazo yo mismo.",
  ui_story_5026_50260501_40_dialog_content = "¡Ay, Nina! ¡Espérame!",
  ui_story_5026_50260501_41_dialog_content = "<color=#e8d9bb>Jardines de nubes: sala de herramientas</color>",
  ui_story_5026_50260501_42_dialog_content = "¡Puaj! ¡Está tan polvoriento aquí!",
  ui_story_5026_50260501_43_dialog_content = "Hay muchos muebles a medio armar. ¿Son todas estas obras maestras creadas por Caelestite?",
  ui_story_5026_50260501_44_dialog_content = "yo no fijé PlayerName ser tan trabajador.",
  ui_story_5026_50260501_45_dialog_content = "Su escasez los haría valiosos. Si se enviaran a la casa de subastas de Umbraton como obras de arte de Caelestita, probablemente alcanzarían buenos precios.",
  ui_story_5026_50260501_46_dialog_content = "Y podrían empaquetarse muy bien, incluso exhibirse en una exhibición...",
  ui_story_5026_50260501_47_dialog_content = "No. Ahora no es el momento de pensar en esas cosas.",
  ui_story_5026_50260501_48_dialog_content = "Herramientas... ¿Dónde están las herramientas? Está demasiado oscuro aquí...",
  ui_story_5026_50260501_49_dialog_content = "<color=#e8d9bb>Whoosh.</color>",
  ui_story_5026_50260501_50_dialog_content = "<size=45>¿Eh? ¡Ah!</size>",
  ui_story_5026_50260501_51_dialog_content = "Era solo el viento. Lo sabía...",
  ui_story_5026_50260501_52_dialog_content = "<color=#e8d9bb>Sonido metálico...</color>",
  ui_story_5026_50260501_53_dialog_content = "<size=45>¡¿Eh?!</size>",
  ui_story_5026_50260501_54_dialog_content = "Debe... Debe ser un Chubb escondido detrás de los muebles...",
  ui_story_5026_50260501_55_dialog_content = "N-No te escondas en la oscuridad... ¡Sal!",
  ui_story_5026_50260501_56_dialog_content = "No tengo miedo en absoluto. Ni un poco...",
  ui_story_5026_50260501_57_dialog_content = "<size=45>Aaaaah!</size>",
  ui_story_5026_50260501_58_dialog_content = "<anim type=Shake><size=50>Graaagh!</size></anim>",
  ui_story_5026_50260501_59_dialog_content = "¿En serio? Así que no era un fantasma...",
  ui_story_5026_50260501_60_dialog_content = "¡Cómo se atreve a asustarme un simple Eclipsite!",
  ui_story_5026_50260502_1_dialog_content = "¿Estás bien, Nina?",
  ui_story_5026_50260502_2_dialog_content = "Creí haber oído un grito antes.",
  ui_story_5026_50260502_3_dialog_content = "¡Oíste mal! ¡E-Este almacén no es oscuro ni da miedo!",
  ui_story_5026_50260502_4_dialog_content = "Fueron solo algunos eclipses, ¡pero me enfrenté a ellos fácilmente!",
  ui_story_5026_50260502_5_dialog_content = "Es bueno que estés bien. ¿Has encontrado la herramienta adecuada?",
  ui_story_5026_50260502_6_dialog_content = "Mientras estabas ocupado buscando herramientas, Minos, él... ya dio vuelta todo el lugar.",
  ui_story_5026_50260502_7_dialog_content = "¡¿Qué?!",
  ui_story_5026_50260502_8_dialog_content = "Está con los Chubb ahora mismo, restaurando el césped como estaba. La regó, y hasta contó el número de lombrices...",
  ui_story_5026_50260502_9_dialog_content = "Ya veo. Así es realmente tener a Minos como oponente.",
  ui_story_5026_50260502_10_dialog_content = "Engañarme para que comiera más verduras y evitar que le hiciera bromas a la institutriz era solo un juego de niños.",
  ui_story_5026_50260502_11_dialog_content = "¿Minos y tú os conocéis desde hace mucho tiempo?",
  ui_story_5026_50260502_12_dialog_content = "Sí, mucho tiempo. Y lo he tolerado durante mucho tiempo también.",
  ui_story_5026_50260502_13_dialog_content = "Ya he tenido suficiente de que él y mi padre me traten como a una niña.",
  ui_story_5026_50260502_14_dialog_content = "¡Bien, pasemos a la siguiente ronda de la prueba!",
  ui_story_5026_50260502_15_dialog_content = "La tercera vez es la vencida. No voy a perder contra Minos otra vez.",
  ui_story_5026_50260502_16_dialog_content = "A continuación, vamos a buscar mineral.",
  ui_story_5026_50260502_17_dialog_content = "Huh... ¿Cloud Gardens tiene minerales locales especiales?",
  ui_story_5026_50260502_18_dialog_content = "Mi familia, quiero decir, mis socios comerciales, la familia Andersen, maneja la mitad de los minerales de Umbraton.",
  ui_story_5026_50260502_19_dialog_content = "Si puedo encontrar un depósito de mineral raro aquí, apuesto a que impresionaría a la cabeza de la familia, ¿verdad?",
  ui_story_5026_50260502_20_dialog_content = "¿La mitad de los minerales? Esta familia Andersen suena realmente impresionante.",
  ui_story_5026_50260502_21_dialog_content = "¿Quién sabe? ¡Solo tengo una relación comercial con ellos!",
  ui_story_5026_50260502_22_dialog_content = "Lo que más me preocupa es cómo se pueden usar los minerales, especialmente las gemas.",
  ui_story_5026_50260502_23_dialog_content = "El proceso de seleccionarlos, evaluarlos, enviarlos para cortarlos, establecerlos—",
  ui_story_5026_50260502_24_dialog_content = "Luego incorpore personalmente cada gema como parte de un arma, pieza de joyería o atuendo.",
  ui_story_5026_50260502_25_dialog_content = "¿Puedes diseñar tantas cosas? Eres increíble, Nina.",
  ui_story_5026_50260502_26_dialog_content = "Jejeje, mis obras son muy populares en Umbraton...",
  ui_story_5026_50260502_27_dialog_content = "...",
  ui_story_5026_50260502_28_dialog_content = "<size=33>... Pero recientemente aprendí que esta popularidad podría no provenir de mis propias habilidades.</size>",
  ui_story_5026_50260502_29_dialog_content = "¿Cómo?",
  ui_story_5026_50260502_30_dialog_content = "Nada. Vi muchos muebles en el almacén. ¿Hiciste esos?",
  ui_story_5026_50260502_31_dialog_content = "Sí. Solo soy un principiante, pero recientemente encontré placer en hacer muebles y construir edificios.",
  ui_story_5026_50260502_32_dialog_content = "¿Vaya? ¿Así que diseñaste todos los muebles y estructuras que he visto en Cloud Gardens?",
  ui_story_5026_50260502_33_dialog_content = "Ah... Bueno, acabo de encontrar planos en varias partes alrededor del área de estructuras antiguas de Caelestite y restauré los originales.",
  ui_story_5026_50260502_34_dialog_content = "¿Qué diversión hay al copiar diseños del pasado?",
  ui_story_5026_50260502_35_dialog_content = "Cuando lo pones así, yo...",
  ui_story_5026_50260502_36_dialog_content = "Estaba fuera de lugar.",
  ui_story_5026_50260502_37_dialog_content = "¿Eh?",
  ui_story_5026_50260502_38_dialog_content = "Tienes tus propias razones. No debería criticar tus sentimientos.",
  ui_story_5026_50260502_39_dialog_content = "No.",
  ui_story_5026_50260502_40_dialog_content = "Tu pregunta me hace pensar seriamente por primera vez en por qué restaurar cosas me hace feliz.",
  ui_story_5026_50260502_41_dialog_content = "¿Por qué?",
  ui_story_5026_50260502_42_dialog_content = "Parece que de esta manera podría recrear algunos de los escenarios que se han perdido en el tiempo y la guerra...",
  ui_story_5026_50260502_43_dialog_content = "Y es casi como si eso ahuyentara la soledad.",
  ui_story_5026_50260502_44_dialog_content = "... No eres exactamente lo que imaginaba, PlayerName.",
  ui_story_5026_50260502_45_dialog_content = "¿Quieres decir?",
  ui_story_5026_50260502_46_dialog_content = "Sanae a menudo me habla de cierta columna en el Umbraton Daily que pretende detallar con precisión la vida de PlayerName la Caelestita.",
  ui_story_5026_50260502_47_dialog_content = "Papá dice que el periódico publica más tonterías en sus páginas que las falsificaciones del Mercado de la Niebla Nocturna.",
  ui_story_5026_50260502_48_dialog_content = "¿Alguien realmente escribe una columna sobre mí?",
  ui_story_5026_50260502_49_dialog_content = "Eres más popular de lo que crees, lo sabes.",
  ui_story_5026_50260502_50_dialog_content = "Recuerdo el título del primer artículo. \"¡Impactante! ¡Un adolescente vuelve a la vida después de estar enterrado durante diecisiete años!\"",
  ui_story_5026_50260502_51_dialog_content = "Si está interesado, Sanae conserva sin falta recortes de los artículos de cada semana y los guarda en un álbum de recortes...",
  ui_story_5026_50260502_52_dialog_content = "También compró el libro que es una publicación de todos los artículos en un volumen.",
  ui_story_5026_50260502_53_dialog_content = "... Por favor, dígame cómo hacer que dejen de escribir.",
  ui_story_5026_50260502_54_dialog_content = "Interesante. ¿Estás tratando de tomar el control de la narrativa?",
  ui_story_5026_50260502_55_dialog_content = "De hecho, como un nuevo poder que apenas está surgiendo, es importante que usted también administre su imagen.",
  ui_story_5026_50260502_56_dialog_content = "No, solo me parece vergonzoso...",
  ui_story_5026_50260502_57_dialog_content = "Eres un pedazo de carne reluciente para los tabloides. Mejor ten cuidado y mantén tus secretos cerca.",
  ui_story_5026_50260502_58_dialog_content = "Tendré cuidado...",
  ui_story_5026_50260502_59_dialog_content = "¡Oh, no! ¡No me di cuenta de que hemos estado chateando durante tanto tiempo!",
  ui_story_5026_50260502_60_dialog_content = "Sanae y Minos probablemente todavía estén esperando. ¡Será mejor que partamos ahora para ir a los minerales!",
  ui_story_5026_50260502_61_dialog_content = "Espero que no nos encontremos con más eclipses en nuestro camino hacia allí.",
  ui_story_5026_50260702_1_dialog_content = "¿De dónde vinieron todos estos eclipses en primer lugar?",
  ui_story_5026_50260702_2_dialog_content = "¿Es su presencia realmente tan sorprendente para ti? Es la norma ser constantemente molestado por eclipses aquí en este continente.",
  ui_story_5026_50260702_3_dialog_content = "Vivía en el Coloso antes de esto, así que nunca lo experimenté realmente...",
  ui_story_5026_50260702_4_dialog_content = "No hace falta decir que hay granjas, bosques y ranchos alrededor de Umbraton. Incluso los pescadores a lo largo del Río Dorado lo saben.",
  ui_story_5026_50260702_5_dialog_content = "Los tiempos de paz son escasos y preciosos.",
  ui_story_5026_50260702_6_dialog_content = "No puedes volar en el cielo ni esconderte bajo tierra aquí, y tampoco está bajo la protección de ningún Auroriano poderoso.",
  ui_story_5026_50260702_7_dialog_content = "Entonces, por el contrario, no veo cómo Cloud Gardens podría estar exento de las intrusiones de Eclipsite.",
  ui_story_5026_50260702_8_dialog_content = "¿A menos que Caelestites y Aurorians sean decisivamente diferentes en la forma en que tratamos con Eclipsites?",
  ui_story_5026_50260702_9_dialog_content = "(¡Qué pregunta tan aguda!)",
  ui_story_5026_50260702_10_dialog_content = "Escuché que Caelestites no podía usar Luminatics para pelear.",
  ui_story_5026_50260702_11_dialog_content = "Tampoco puedes usar Luminatics para manipular herramientas, como lo estoy haciendo ahora mismo, así que no tengo que realizar trabajo físico por mi cuenta.",
  ui_story_5026_50260702_12_dialog_content = "Parece que necesitas mover tu pico tres o cuatro veces solo para cortar un trozo de mineral...",
  ui_story_5026_50260702_13_dialog_content = "<color=#e8d9bb>¡Bam!</color>",
  ui_story_5026_50260702_14_dialog_content = "¡Ay! ¿Eso te lastimó? ¡Lo siento!",
  ui_story_5026_50260702_15_dialog_content = "<anim type=Shake>Cachero...</anim>",
  ui_story_5026_50260702_16_dialog_content = "Aunque puedo manejar bastante bien las armas, me lleva algo de tiempo acostumbrarme al peso de estas herramientas y a cómo se usan...",
  ui_story_5026_50260702_17_dialog_content = "¿Dónde estábamos antes, PlayerName?",
  ui_story_5026_50260702_18_dialog_content = "Oh, sí, lo que aprendí sobre las habilidades de Caelestites es que no son tan útiles para defender el territorio...",
  ui_story_5026_50260702_19_dialog_content = "Pero Caelestites puede ordenar a los aurorianos que luchen de manera eficiente, así que, ¿sus ancestros emplearon aurorianos como guardias?",
  ui_story_5026_50260702_20_dialog_content = "Si hubo comunicación frecuente entre las dos razas, debería haber más información en la biblioteca de Padre que—",
  ui_story_5026_50260702_21_dialog_content = "<size=45>¡Guau!</size>",
  ui_story_5026_50260702_22_dialog_content = "¿Q-Qué pasó? ¿Se mantienen unidos porque quieren vengarse de su amigo?",
  ui_story_5026_50260702_23_option_content = "No, no creo que sea eso.",
  ui_story_5026_50260702_24_option_content = "¿Debería intentar usar mi habilidad?",
  ui_story_5026_50260702_25_dialog_content = "(Hablando de eso, nunca he pensado en lo que pasa por la mente de los Chubb).",
  ui_story_5026_50260702_26_dialog_content = "¡Ayuda Chubb!",
  ui_story_5026_50260702_27_dialog_content = "Chicos... ¿Me están ayudando a clasificar los minerales que extrajimos?",
  ui_story_5026_50260702_28_dialog_content = "¡Cachero!",
  ui_story_5026_50260702_29_dialog_content = "Está bien, quédate con este. Debe ser de hierro, que se puede utilizar para fabricar herramientas.",
  ui_story_5026_50260702_30_dialog_content = "También hay cuarzo, pero la finura puede ser un problema, por lo que solo se puede usar como material de construcción.",
  ui_story_5026_50260702_31_dialog_content = "¡Ah, eso podría ser una piedra preciosa en bruto! ¡Sé amable con eso!",
  ui_story_5026_50260702_32_dialog_content = "¡Entendido, Chubb!",
  ui_story_5026_50260702_33_dialog_content = "Qué adorables... ejem... quiero decir, maravillosas criaturas.",
  ui_story_5026_50260702_34_dialog_content = "Parece que Cloud Gardens tiene su propio sistema único tanto para la seguridad como para la producción.",
  ui_story_5026_50260702_35_dialog_content = "(¿Sistema único? Todavía no me he tomado el tiempo para pensar en esto antes).",
  ui_story_5026_50260702_36_dialog_content = "(Mi primera impresión de Nina fue que no estaba muy versada en asuntos mundanos, y su plan de dominación también sonaba bastante descabellado).",
  ui_story_5026_50260702_37_dialog_content = "(¡Pero no hay duda de su profesionalismo cuando se trata de asuntos comerciales!)",
  ui_story_5026_50260702_38_dialog_content = "(Mientras tanto, yo... ni siquiera sé mucho sobre este lugar al que llamo hogar).",
  ui_story_5026_50260702_39_dialog_content = "(Yo soy el que está en libertad condicional aquí, ¿verdad? ¿Podré pasar?)",
  ui_story_5026_50260702_40_dialog_content = "Parece estar muy interesado en las operaciones de Cloud Gardens.",
  ui_story_5026_50260702_41_dialog_content = "Después de todo, aquí es donde comienza el plan de dominación mundial que se me ocurrió. Es natural aprender tanto como sea posible al respecto, ¿verdad?",
  ui_story_5026_50260702_42_dialog_content = "Pareces de la misma edad que yo, pero eres realmente impresionante.",
  ui_story_5026_50260702_43_dialog_content = "¿Q-Qué? No tienes nada que ganar con halagarme así.",
  ui_story_5026_50260702_44_dialog_content = "A continuación, es hora de contar nuestros resultados.",
  ui_story_5026_50260702_45_dialog_content = "Me las arreglé para conseguir bastante. Esta vez no perderé contra Minos, ¿verdad?",
  ui_story_5026_50260702_46_dialog_content = "¡Increíble, Chubb!",
  ui_story_5026_50260702_47_dialog_content = "¡El maestro también es increíble, Chubb!",
  ui_story_5026_50260702_48_dialog_content = "¿Maestro?",
  ui_story_5026_50260702_49_dialog_content = "Hay una pila de minerales aún más grande junto a la tuya. ¿Son estos los que extrajo Minos?",
  ui_story_5026_50260702_50_dialog_content = "¡¿C-cuándo fueron sobornados por Minos?!",
  ui_story_5026_50260702_51_dialog_content = "Eh... señorita...",
  ui_story_5026_50260702_52_dialog_content = "¡Quiero decir, Nina!",
  ui_story_5026_50260702_53_dialog_content = "¿Cómo es de tu parte? Acordamos confirmar la ubicación de un depósito de mineral, pero ya no puedo excavar. Y yo...",
  ui_story_5026_50260702_54_dialog_content = "... ¡Tengo tanta hambre!",
  ui_story_5026_50260702_55_dialog_content = "¿Quién habló hace un momento?",
  ui_story_5026_50260702_56_dialog_content = "<size=45>¡Aaah! M-Manae!</size>",
  ui_story_5026_50260702_57_dialog_content = "Sin trabajo, sin comida, lo entiendo... ¿Pero ni siquiera tomamos un sorbo de agua después de horas de excavación?",
  ui_story_5026_50260702_58_dialog_content = "¡Incluso la mina en la que trabajamos antes en la oscuridad de la noche sin el permiso del Señor de las Sombras no fue tan explotadora!",
  ui_story_5026_50260702_59_dialog_content = "Manae! ¡Shh!",
  ui_story_5026_50260702_60_dialog_content = "¡Lo siento! Ni siquiera tomé eso en consideración. ¡Te traeré un poco de agua ahora mismo!",
  ui_story_5026_50260702_61_dialog_content = "(¿Eh? ¿Las muñecas también necesitan agua?)",
  ui_story_5026_50260702_62_dialog_content = "(Estaba tan preocupado por la reprimenda que le pedí disculpas a una muñeca sin darme cuenta...)",
  ui_story_5026_50260702_63_dialog_content = "(No, no, no, más importante...)",
  ui_story_5026_50260702_64_dialog_content = "<size=45>¿Hablaba?</size>",
  ui_story_5026_50260702_65_dialog_content = "¿Estoy alucinando porque estoy muy cansada?",
  ui_story_5026_50260702_66_dialog_content = "¿Por qué no se toma un descanso, Sr. Navegante?",
  ui_story_5026_50260702_67_dialog_content = "Todos, por favor siéntense aquí.",
  ui_story_5026_50260702_68_dialog_content = "¿De dónde vienen estas mesas y sillas?",
  ui_story_5026_50260702_69_dialog_content = "¿Y de dónde vienen estos bocadillos?",
  ui_story_5026_50260702_70_dialog_content = "Tomé prestada tu cocina con la ayuda de Chubbs. ¿Los bocadillos son de tu agrado?",
  ui_story_5026_50260702_71_dialog_content = "son tan buenos...",
  ui_story_5026_50260702_72_dialog_content = "(Waah, lo sabía. La mala comida en Cloud Gardens no se debió a la cocina).",
  ui_story_5026_50260702_73_dialog_content = "Sr. Navegante, ¿lo asusté antes?",
  ui_story_5026_50260702_74_dialog_content = "Esta marioneta es Manae. A veces abre la boca de la nada y dice cosas incómodas.",
  ui_story_5026_50260702_75_dialog_content = "Sé que ella solo está cuidando de mí, pero...",
  ui_story_5026_50260702_76_dialog_content = "Sanae, el té se está desbordando.",
  ui_story_5026_50260702_77_dialog_content = "<size=45>¡Lo siento!</size>",
  ui_story_5026_50260702_78_dialog_content = "Dos terrones de azúcar, revueltos diez veces en el sentido de las agujas del reloj y tres veces en el sentido contrario a las agujas del reloj. Aquí, señorita Nina.",
  ui_story_5026_50260702_79_dialog_content = "Uh-hum.",
  ui_story_5026_50260702_80_dialog_content = "(Nina parece acostumbrada a esto...)",
  ui_story_5026_50260702_81_dialog_content = "(¿Está realmente bien para mí estar relajado así cuando los Eclipsites corren por todo Cloud Gardens?)",
  ui_story_5026_50260702_82_dialog_content = "(Pero de todos modos, no es como si el estrés arreglara algo).",
  ui_story_5026_50260702_83_dialog_content = "(Como preguntó Nina antes, ¿cómo se defendían los Caelestitas de los intrusos en el pasado?)",
  ui_story_5026_50260702_84_dialog_content = "(Contratar Aurorianos como guardaespaldas era obviamente imposible.)",
  ui_story_5026_50260702_85_dialog_content = "(Si el Obelisco del Retorno era el único medio de defensa aquí, ¿qué debo hacer ahora que se ha quedado en silencio?)",
  ui_story_5026_50260702_86_dialog_content = "(Incluso si hay otras armas dejadas por los antiguos Caelestitas, ¿podrían sus enemigos—)",
  ui_story_5026_50260702_87_dialog_content = "¿En qué estás pensando tanto?",
  ui_story_5026_50260702_88_dialog_content = "¡N-Nada!",
  ui_story_5026_50260702_89_dialog_content = "La hora del té es un momento sagrado en el que no se debe entrometerse. No pienses en cosas innecesarias.",
  ui_story_5026_50260702_90_dialog_content = "Es importante permitirse reducir la velocidad de vez en cuando.",
  ui_story_5026_50260702_91_dialog_content = "Pero si tienes dudas sobre lo que hemos hecho hasta ahora, no dudes en decírnoslo.",
  ui_story_5026_50260702_92_dialog_content = "No es realmente duda, pero tengo curiosidad acerca de algo.",
  ui_story_5026_50260702_93_dialog_content = "¿Cuál es la relación entre ustedes tres y por qué solicitaron el puesto de gerente en Cloud Gardens?",
  ui_story_5026_50260702_94_dialog_content = "No pareces estar acostumbrado al trabajo físico.",
  ui_story_5026_50260702_95_dialog_content = "¿¡T-Puedes decirlo!?",
  ui_story_5026_50260702_96_dialog_content = "Y Sanae no es lo suficientemente meticulosa para ser buena en las tareas del hogar.",
  ui_story_5026_50260702_97_dialog_content = "P-Pero yo... <size=45>¡Ahhhh! ¡Las tazas!</size>",
  ui_story_5026_50260702_98_dialog_content = "Minos en cambio... es impecable hasta el punto de horrorizar. Obviamente puedes encontrar un trabajo mejor.",
  ui_story_5026_50260702_99_dialog_content = "Gracias por el cumplido, pero solo soy un simple mayordomo.",
  ui_story_5026_50260702_100_dialog_content = "No malinterpretes. ¡No estoy criticando a ninguno de ustedes!",
  ui_story_5026_50260702_101_dialog_content = "Estoy seguro de que debe haber una razón para que ustedes tengan sus secretos.",
  ui_story_5026_50260702_102_dialog_content = "Sin ti, no podría haber manejado tantos eclipses.",
  ui_story_5026_50260702_103_dialog_content = "Y ustedes me hicieron darme cuenta de que Cloud Gardens necesita mucho más trabajo.",
  ui_story_5026_50260702_104_dialog_content = "Minos me llamó el Amo de los Jardines de las Nubes, y los Chubbs también me llaman el Amo...",
  ui_story_5026_50260702_105_dialog_content = "Pero, ¿realmente merezco este título?",
  ui_story_5026_50260702_105X1_dialog_content = "En lugar de perder el tiempo dudando de ti mismo, debes pensar en lo que puedes hacer para merecer el título.",
  ui_story_5026_50260702_105X2_dialog_content = "Al menos, eso es lo que yo haría.",
  ui_story_5026_50260702_105X3_dialog_content = "Pero contrariamente a mi sugerencia, creo que lo que más necesitas ahora es...",
  ui_story_5026_50260702_106_dialog_content = "...",
  ui_story_5026_50260702_107_dialog_content = "PlayerName, ¿hay algún lugar que te guste especialmente en Cloud Gardens?",
  ui_story_5026_50260702_108_dialog_content = "Cuando necesito relajarme, voy a pescar.",
  ui_story_5026_50260702_109_dialog_content = "Pero me encontré con Eclipsites en mi camino allí la última vez...",
  ui_story_5026_50260702_110_dialog_content = "¿Por qué preguntas, quieres—",
  ui_story_5026_50260702_110X1_dialog_content = "¡N-Definitivamente no es porque quiera que te relajes ni nada!",
  ui_story_5026_50260702_111_dialog_content = "¡Conocer los pasatiempos de mis socios comerciales es parte del trabajo!",
  ui_story_5026_50260702_112_dialog_content = "Ahora que te has dado cuenta, termina tu té y vámonos.",
  ui_story_5026_50260801_1_dialog_content = "<color=#e8d9bb>Eraveil: Desierto</color>",
  ui_story_5026_50260801_2_dialog_content = "Hmm... Todavía estoy un poco preocupado.",
  ui_story_5026_50260801_3_dialog_content = "Solo me enteré de la situación en la casa de los Andersen después de volver a Umbraton para preguntar...",
  ui_story_5026_50260801_4_dialog_content = "¿Qué sucede?",
  ui_story_5026_50260801_5_dialog_content = "¡Oh hola! ¡Llegamos al río sanos y salvos esta vez!",
  ui_story_5026_50260801_6_dialog_content = "La última vez que vine a pescar, de repente aparecieron Eclipsites. No sé qué hubiera pasado si Bethel no hubiera estado allí.",
  ui_story_5026_50260801_7_dialog_content = "Probablemente me habría pinchado con una brizna de hierba considerando lo mucho que Spikepest arruinó el lugar.",
  ui_story_5026_50260801_8_dialog_content = "¿Están usted y Bethel muy unidos?",
  ui_story_5026_50260801_9_dialog_content = "Luchamos codo con codo con Luke de los Mercenarios de la Llama Blanca en el incidente del Gremio del León Azul.",
  ui_story_5026_50260801_10_dialog_content = "Nos cruzamos a veces después. Esa vez que me salvó, en realidad había venido en nombre de Sheol y el Cloudrover Guild.",
  ui_story_5026_50260801_11_dialog_content = "Hmph. Ya veo.",
  ui_story_5026_50260801_12_dialog_content = "Es una comerciante impresionante. Ha hecho un buen trabajo administrando el gremio de Istvan.",
  ui_story_5026_50260801_13_dialog_content = "De vuelta en Dawn Academy, todos también cantaron alabanzas a Bethel.",
  ui_story_5026_50260801_14_dialog_content = "¡N-No pienses demasiado! ¡No es que me importe lo que pasa entre ustedes dos!",
  ui_story_5026_50260801_15_dialog_content = "(Así que a ella le importa.)",
  ui_story_5026_50260801_16_dialog_content = "Dijiste que la pesca era parte de tus tareas diarias aquí, ¿verdad?",
  ui_story_5026_50260801_17_dialog_content = "Si ese es el caso, no se puede tratar como cualquier actividad casual.",
  ui_story_5026_50260801_18_dialog_content = "Una vez. Solo una vez, necesito vencer a Minos.",
  ui_story_5026_50260801_19_dialog_content = "Sin embargo, solo había una caña de pescar y los Chubbs se la dieron a Minos.",
  ui_story_5026_50260801_20_dialog_content = "¿Qué?",
  ui_story_5026_50260801_21_dialog_content = "Lo sé. Es un poco complicado sin una caña de pescar.",
  ui_story_5026_50260801_22_dialog_content = "¿¡Qué lo hace tan popular entre los Chubbs!?",
  ui_story_5026_50260801_23_dialog_content = "Así que eso es lo que realmente te importa...",
  ui_story_5026_50260801_24_dialog_content = "Solo para igualar las probabilidades, te enseñaré a pescar sin caña de pescar.",
  ui_story_5026_50260801_25_dialog_content = "¡En el Lejano Oriente, todos me llaman el gran \"maestro del pez dorado\"!",
  ui_story_5026_50260801_26_dialog_content = "Incluso si no tengo las herramientas que tenía allí y los peces son diferentes, bueno... siguen siendo peces, ¿verdad?",
  ui_story_5026_50260801_27_dialog_content = "...",
  ui_story_5026_50260801_28_dialog_content = "Sanae, me dijiste una vez que solías pescar en el río cuando eras joven. ¿Qué tal si me enseñas?",
  ui_story_5026_50260801_29_dialog_content = "(¡Ella me ignoró!)",
  ui_story_5026_50260801_30_dialog_content = "Ah... Ajaja... ¡jaja! Creo que vi algunos peces por allí hace un momento. ¡Iré a comprobarlo!",
  ui_story_5026_50260801_31_dialog_content = "PlayerNamese ha ido...",
  ui_story_5026_50260801_32_dialog_content = "Señorita Nina, usted... ¡Atrapar peces está por debajo de usted! ¡Porfavor me permite!",
  ui_story_5026_50260801_33_dialog_content = "Ser capaz de atrapar un pez o no solía significar la diferencia entre la vida y la muerte para mí.",
  ui_story_5026_50260801_34_dialog_content = "Aunque puede que no sea tan bueno como el renombrado PlayerName¡Todavía daré lo mejor de mí!",
  ui_story_5026_50260801_35_dialog_content = "Me llamaste \"Señorita Nina\" otra vez, ¿no?",
  ui_story_5026_50260801_36_dialog_content = "¡Ay! ¡Lo siento por eso!",
  ui_story_5026_50260801_37_dialog_content = "No me preocupa revelar mi identidad. Si no me equivoco, PlayerName realmente no le importa",
  ui_story_5026_50260801_38_dialog_content = "Nunca ha oído hablar del Conde Andersen. Anticipé eso.",
  ui_story_5026_50260801_39_dialog_content = "Puede que mi padre posea muchas tierras en Astra, pero para los caelestitas es un anciano cualquiera.",
  ui_story_5026_50260801_40_dialog_content = "De alguna manera, eso me hace feliz.",
  ui_story_5026_50260801_41_dialog_content = "N-Nina...",
  ui_story_5026_50260801_42_dialog_content = "Así es, Sanae. Aquí solo soy Nina. Y... pescar parece divertido.",
  ui_story_5026_50260801_43_dialog_content = "Solo vi gente haciéndolo junto al río Gold cada vez que pasaba por allí. He estado ansiosa por intentarlo.",
  ui_story_5026_50260801_44_dialog_content = "U-Um Nina... Tu vestido es un poco largo para pescar.",
  ui_story_5026_50260801_45_dialog_content = "Está bien. Lo aguantaré.",
  ui_story_5026_50260801_46_dialog_content = "Todo lo que necesita es decirme cómo bloquear el objetivo, y mi Luminatic hará el resto.",
  ui_story_5026_50260801_47_dialog_content = "¡Ay! ¡El agua está tan fría!",
  ui_story_5026_50260801_48_dialog_content = "Los guijarros en el agua son resbaladizos. ¡Cuida tu paso!",
  ui_story_5026_50260801_49_dialog_content = "Si el Sr. Minos estuviera aquí, probablemente te recordaría que cuides tu estatus y seas elegante.",
  ui_story_5026_50260801_50_dialog_content = "Pero parece estar preocupado por otra cosa en este momento.",
  ui_story_5026_50260801_51_dialog_content = "Déjame mostrarte cómo atrapar peces.",
  ui_story_5026_50260801_52_dialog_content = "Primero, quédese quieto en el agua, al igual que sus pies están enraizados en el lecho del río.",
  ui_story_5026_50260801_53_dialog_content = "Luego observe el movimiento del pez y elija su objetivo.",
  ui_story_5026_50260801_54_dialog_content = "¡Oye! Ese es un pez globo de allí. ¡Es delicioso al vapor!",
  ui_story_5026_50260801_55_dialog_content = "Ese pez cuchillo haría un buen asado...",
  ui_story_5026_50260801_56_dialog_content = "<size=45>Jejeje... ¡Jajajaja!</size>",
  ui_story_5026_50260801_57_dialog_content = "¿Q-Qué? ¡Oh lo siento! Acabo de comer bocadillos, y ahora estoy...",
  ui_story_5026_50260801_58_dialog_content = "Está bien. Estaba pensando, esto es tan tuyo.",
  ui_story_5026_50260801_59_dialog_content = "Eres bastante hablador una vez que encuentras algo de lo que te gusta hablar.",
  ui_story_5026_50260801_60_dialog_content = "Eso es cierto... ¿Es raro?",
  ui_story_5026_50260801_61_dialog_content = "De lo contrario. Lo encuentro bastante lindo.",
  ui_story_5026_50260801_62_dialog_content = "Hmm... ¿D-dónde estábamos ahora?",
  ui_story_5026_50260801_63_dialog_content = "Observa los peces y elige tu objetivo.",
  ui_story_5026_50260801_64_dialog_content = "¡Derecha! Ahora, mata cuando el pez todavía esté desprevenido...",
  ui_story_5026_50260801_65_dialog_content = "<size=45>¡Ahora!</size>",
  ui_story_5026_50260801_66_dialog_content = "¡Entendido!",
  ui_story_5026_50260801_67_dialog_content = "¡Asombroso!",
  ui_story_5026_50260801_68_dialog_content = "Jeje...",
  ui_story_5026_50260801_69_dialog_content = "Déjame probar... ¡Vaya! ¡Es tan resbaladizo!",
  ui_story_5026_50260801_70_dialog_content = "Se escapó...",
  ui_story_5026_50260801_71_dialog_content = "¿Es así como lo hace el gran Goldfish Master, PlayerName? Estoy sin palabras.",
  ui_story_5026_50260801_72_dialog_content = "¡Es más fácil decirlo que hacerlo! ¡Intenta!",
  ui_story_5026_50260801_73_dialog_content = "¡Decir ah! ¡Solo mírame!",
  ui_story_5026_50260801_74_dialog_content = "Miss Nina seguro que se está divirtiendo.",
  ui_story_5026_50260801_75_dialog_content = "¿Eh? Pensé que estabas pescando con Nina. PlayerName?",
  ui_story_5026_50260801_76_dialog_content = "La está pasando muy bien con Sanae, así que pensé que sería mejor dejarlos solos.",
  ui_story_5026_50260801_77_dialog_content = "Pero ¿por qué estás de vuelta? Oye, ¿Sheol rechazó mi solicitud de posponer el pago?",
  ui_story_5026_50260801_78_dialog_content = "No, eso va bien, pero...",
  ui_story_5026_50260801_79_dialog_content = "Sr. Minos, ¿es cierto que el Conde Andersen ha estado rechazando visitantes debido a problemas de salud?",
  ui_story_5026_50260801_80_dialog_content = "Parece que ya lo ha oído, Lady Bethel.",
  ui_story_5026_50260801_81_dialog_content = "...",
  ui_story_5026_50260801_82_dialog_content = "(¿Minos solo me estaba evaluando? ¿O me equivoqué?)",
  ui_story_5026_50260801_83_dialog_content = "De hecho, eso sucedió después de que la señorita Nina se escapó de su casa y dijo \"¡Te odio, papá!\"...",
  ui_story_5026_50260801_84_dialog_content = "El Maestro canceló todas las reuniones y se encerró en su habitación.",
  ui_story_5026_50260801_85_dialog_content = "Espera un minuto. Entonces, ¿quién está manejando todos los asuntos relacionados con sus propiedades y tierras en este momento?",
  ui_story_5026_50260801_86_dialog_content = "Gracias por su preocupación, Lady Bethel.",
  ui_story_5026_50260801_87_dialog_content = "Pero para mí, ningún asunto es más importante que ambos.",
  ui_story_5026_50260801_88_dialog_content = "¡Padre! ¿Enviaste gente a comprar todos los productos en mi tienda?",
  ui_story_5026_50260801_89_dialog_content = "Nina, querida, ¿de qué estás hablando?",
  ui_story_5026_50260801_90_dialog_content = "Limpiaste mi tienda para que pareciera que eran populares, ¿no es así?",
  ui_story_5026_50260801_91_dialog_content = "De hecho, pensé que lo que diseñé era realmente bueno... pero ahora...",
  ui_story_5026_50260801_92_dialog_content = "Oh, querida... ¡No te enfades!",
  ui_story_5026_50260801_93_dialog_content = "¡Es mi error! Solo quiero darte todo lo que te mereces, ¡las mejores cosas!",
  ui_story_5026_50260801_94_dialog_content = "¡Papá, siempre eres así!",
  ui_story_5026_50260801_95_dialog_content = "¡Cada vez que creo que finalmente he logrado algo por mi cuenta, descubro que estás moviendo los hilos detrás de escena!",
  ui_story_5026_50260801_96_dialog_content = "¿Crees que sin tu ayuda, sin el nombre de Andersen, estoy totalmente indefenso?",
  ui_story_5026_50260801_97_dialog_content = "¡N-No! ¡Por supuesto que no! ¡No es así, Nina!",
  ui_story_5026_50260801_98_dialog_content = "<size=45>¡Te odio, papá!</size>",
  ui_story_5026_50260801_99_dialog_content = "Y así fue como Miss Nina acabó llevándose a Sanae y huyendo.",
  ui_story_5026_50260801_100_dialog_content = "Así que el Amo me envió tras la señorita Nina para traerla de vuelta... Pero no en contra de su voluntad.",
  ui_story_5026_50260801_101_dialog_content = "(Eso suena como una tarea difícil.)",
  ui_story_5026_50260801_102_dialog_content = "De nada. Es parte de mi trabajo.",
  ui_story_5026_50260801_103_dialog_content = "(¿Acaba de leer mi mente?)",
  ui_story_5026_50260801_104_dialog_content = "No leí tu mente. Por favor, siéntete cómodo.",
  ui_story_5026_50260801_105_dialog_content = "Entonces, ¿cómo sabes lo que estoy pensando?",
  ui_story_5026_50260801_106_dialog_content = "Si no le molesta que lo diga, Sr. Navegante, es como un libro abierto.",
  ui_story_5026_50260801_107_dialog_content = "Pero no se parece a nadie que la señorita Nina haya conocido. Esa puede ser la razón por la que ella se abrió a ti.",
  ui_story_5026_50260801_108_dialog_content = "Wow, ¿llamas a nuestras interacciones actuales como si ella se \"abriera\" a mí?",
  ui_story_5026_50260801_109_dialog_content = "Las sombras siempre están mirando, Sr. Navegante. Más de uno, en realidad.",
  ui_story_5026_50260801_110_dialog_content = "Espero que nunca traiciones la confianza de la señorita Nina.",
  ui_story_5026_50260801_111_dialog_content = "No te preocupes. Si lo peor llega a lo peor...",
  ui_story_5026_50260801_112_dialog_content = "La Sra. Sheol aún se aseguraría de que, en términos de negocios, obtener menos ofertas a mitad de precio sea lo único con lo que tenga que lidiar.",
  ui_story_5026_50260801_113_dialog_content = "Por supuesto, también habría consecuencias que no pertenecen a asuntos comerciales.",
  ui_story_5026_50260801_114_dialog_content = "No, no, no, no digas más. ¡Las ofertas a mitad de precio me importan mucho!",
  ui_story_5026_50260801_115_dialog_content = "Gracias por su comprensión.",
  ui_story_5026_50260801_116_dialog_content = "Sin embargo, tengo que dejar algo claro.",
  ui_story_5026_50260801_117_dialog_content = "Para mí, Nina es Nina. Ni su estatus ni su identidad cambiarían cómo la veo.",
  ui_story_5026_50260801_118_dialog_content = "Ella estaría agradecida de oírte decir eso... de verdad.",
  ui_story_5026_50260801_119_dialog_content = "Permíteme preguntarte algo...",
  ui_story_5026_50260801_120_dialog_content = "Si se enfadara conmigo y saliera corriendo gritando: \"PlayerName ¡Es un idiota!\"... ¿Qué pasaría entonces?",
  ui_story_5026_50260801_121_dialog_content = "Morirías, naturalmente.",
  ui_story_5026_50260801_122_dialog_content = "(Siento un escalofrío en la columna... ¡seguro que no me lo imaginaba!)",
  ui_story_5026_50260801_123_dialog_content = "Fue un chiste. No soy un verdugo, solo un simple mayordomo.",
  ui_story_5026_50260801_124_dialog_content = "(¡No parece que esté bromeando en absoluto!)",
  ui_story_5026_50260801_125_dialog_content = "Ha sido un placer conversar con usted, Sr. Navegante. ¿Cómo te gustaría manejar el pescado?",
  ui_story_5026_50260801_126_dialog_content = "¡Vaya, esto es mucho! ¡Y todos son peces ornamentales!",
  ui_story_5026_50260801_127_dialog_content = "Ya hice que los Chubb enviaran los comestibles a la cocina.",
  ui_story_5026_50260801_128_dialog_content = "Si no es mucha molestia, ponga estos peces ornamentales en la Fuente de la Esperanza junto a la Torre Jacinto.",
  ui_story_5026_50260801_129_dialog_content = "Como desées. Ahora, discúlpeme, Lady Bethel, Sr. Navegante.",
  ui_story_5026_50260801_130_dialog_content = "Bethel... ¿Son así los mayordomos de Umbraton?",
  ui_story_5026_50260801_131_dialog_content = "Al igual que en mi gremio, el Señor de las Sombras también tiene subordinados que manejan diferentes cosas.",
  ui_story_5026_50260801_132_dialog_content = "Puede que conozcas a algunos de ellos. Son buenos en lo que hacen y harán lo que sea necesario.",
  ui_story_5026_50260801_133_dialog_content = "En cuanto a la Asociación Andersen, Minos maneja todos estos \"asuntos\" extraños.",
  ui_story_5026_50260801_134_dialog_content = "Es el mejor de los mejores, no hay mayordomos como él.",
  ui_story_5026_50260801_135_dialog_content = "Correcto... Gracias... Bethel.",
  ui_story_5026_50260801_136_dialog_content = "(Tal vez no debí haber preguntado...)",
  ui_story_5026_50260801_137_dialog_content = "¡Nina, Nina! ¡El pez viene hacia ti!",
  ui_story_5026_50260801_138_dialog_content = "...",
  ui_story_5026_50260801_139_dialog_content = "Minos, PlayerName, y... ¿Es eso Bethel?",
  ui_story_5026_50260801_140_dialog_content = "¿Qué están discutiendo entre ellos?",
  ui_story_5026_50260801_141_dialog_content = "Nina, ¿estás escuchando?",
  ui_story_5026_50260801_142_dialog_content = "Nina está mirando en la dirección de esos tres, murmurando para sí misma.",
  ui_story_5026_50260801_143_dialog_content = "Probablemente esté preocupada de que si no puede vencer a Minos, tendrá que irse a casa con él.",
  ui_story_5026_50260801_144_dialog_content = "Sanae, ¿has decidido a quién vas a ayudar?",
  ui_story_5026_50260801_145_dialog_content = "¡No dejaré que Nina pierda!",
  ui_story_5026_50260801_146_dialog_content = "Pero si pierdes este trabajo, volverás a estar en la calle.",
  ui_story_5026_50260801_147_dialog_content = "¡Deja de decirme eso! ¡Voy a atrapar a ese mero, ni siquiera tú me distraerás!",
  ui_story_5026_50260801_148_dialog_content = "¡Ahora!",
  ui_story_5026_50260801_149_dialog_content = "<size=45>=¡Ah</size=45>!",
  ui_story_5026_50260801_150_dialog_content = "<color=#e8d9bb>Plaf...</color>",
  ui_story_5026_50260801_151_dialog_content = "¿Sanae?",
  ui_story_5026_50260801_152_dialog_content = "¿Eh?",
  ui_story_5026_50260901_1_dialog_content = "<anim type=Shake><size=45>¡A-Achoo!</size></anim>",
  ui_story_5026_50260901_2_dialog_content = "¡Toalla, Chubb!",
  ui_story_5026_50260901_3_dialog_content = "Este Chubb es tan considerado...",
  ui_story_5026_50260901_4_dialog_content = "Es solo un pez. ¿Cómo pudiste ser tan descuidado y caer al agua?",
  ui_story_5026_50260901_5_dialog_content = "Incluso se te cayó tu preciada muñeca... Probablemente Manae se asustó.",
  ui_story_5026_50260901_6_dialog_content = "Finalmente encontré algo en lo que soy bueno. yo solo queria ganar...",
  ui_story_5026_50260901_7_dialog_content = "Siento haberte molestado... Debería haberme asegurado de estar de pie correctamente. Debería ser yo quien te cuide...",
  ui_story_5026_50260901_8_dialog_content = "Y mojé tus faldas...",
  ui_story_5026_50260901_9_dialog_content = "Lo siento, Nina, Manae y el Sr. Chubb...",
  ui_story_5026_50260901_10_dialog_content = "Un \"gracias\" es todo lo que se necesita.",
  ui_story_5026_50260901_11_dialog_content = "¿Todavía me tomas por una joven amante a pesar de que ya no estamos en la mansión?",
  ui_story_5026_50260901_12_dialog_content = "P-Pero siempre soy torpe y no puedo hacer nada por ti...",
  ui_story_5026_50260901_13_dialog_content = "¿De qué estás hablando? ¡Si no me hubieras cubierto, no habría manera de que hubiéramos salido de la mansión justo debajo de las narices de Minos!",
  ui_story_5026_50260901_14_dialog_content = "Es una pena que no pude ver su expresión cuando encontró ese agujero en la valla de rosas.",
  ui_story_5026_50260901_15_dialog_content = "No soy muy brillante... siempre leyendo novelas inútiles y soñando despierta...",
  ui_story_5026_50260901_16_dialog_content = "¿Qué tiene eso que ver con que me trates como a una persona normal?",
  ui_story_5026_50260901_17_dialog_content = "En realidad, si no fuera por todas tus historias sobre Cloud Island y los misteriosos Caelestites...",
  ui_story_5026_50260901_18_dialog_content = "Probablemente no me hubiera decidido a dejar Umbraton y ver el mundo a través de mis propios ojos.",
  ui_story_5026_50260901_19_dialog_content = "Todavía estaría sentado en mi habitación, de mal humor por la lluvia o algo así.",
  ui_story_5026_50260901_20_dialog_content = "Así que no necesitas caminar sobre cáscaras de huevo todo el tiempo. Sólo di lo que tienes en mente.",
  ui_story_5026_50260901_21_dialog_content = "Nina...",
  ui_story_5026_50260901_22_dialog_content = "No quiero entrometerme, pero...",
  ui_story_5026_50260901_23_dialog_content = "Según el requerimiento de personal PlayerName me habló, todo lo que necesitamos ahora es un registrador.",
  ui_story_5026_50260901_24_dialog_content = "Hmm...",
  ui_story_5026_50260901_25_dialog_content = "La ropa de la señorita Sanae todavía está húmeda. ¿Por qué no nos tomamos un descanso aquí?",
  ui_story_5026_50260901_26_dialog_content = "Usar Luminatics en un lugar cálido y seco hará que su ropa se seque más rápido.",
  ui_story_5026_50260901_27_dialog_content = "Lo siento⁠, quiero decir, gracias, Lady Bethel.",
  ui_story_5026_50260901_28_dialog_content = "P-Pero... He estado queriendo preguntar... ¿Qué es este lugar?",
  ui_story_5026_50260901_29_dialog_content = "PlayerName Chubb nos trajo aquí para descansar.",
  ui_story_5026_50260901_30_dialog_content = "¡Es el más cercano! ¡Y aquí hay toallas, Chubb!",
  ui_story_5026_50260901_31_dialog_content = "Pero esta parece ser la habitación del Sr. Navegante...",
  ui_story_5026_50260901_32_dialog_content = "Ha sido amable con nosotros. Debería tratar de arreglar este lugar para él.",
  ui_story_5026_50260901_33_dialog_content = "Quieres decir... Esto es...",
  ui_story_5026_50260901_34_dialog_content = "¡Nunca he estado dentro de la habitación de un chico!",
  ui_story_5026_50260901_35_dialog_content = "¿P-Por qué te tapas los ojos, Nina?",
  ui_story_5026_50260901_36_dialog_content = "La realidad es bastante diferente de la ficción, ¿no es así?",
  ui_story_5026_50260901_37_dialog_content = "¿Señora Betel?",
  ui_story_5026_50260901_38_dialog_content = "En realidad, la pregunta más importante es, ¿por qué estás tan tranquila, Sanae?",
  ui_story_5026_50260901_39_dialog_content = "Yo... serví en muchos hogares antes de venir a los Andersen.",
  ui_story_5026_50260901_40_dialog_content = "Así que he limpiado las habitaciones de muchos niños.",
  ui_story_5026_50260901_41_dialog_content = "Recuerdo cosas como ropa sucia escondida debajo de camas hechas...",
  ui_story_5026_50260901_42_dialog_content = "Estantes llenos de figuritas que no me permitían tocar aunque estuvieran llenas de polvo...",
  ui_story_5026_50260901_43_dialog_content = "Montones de cosas que se me caían encima en cuanto abría el armario...",
  ui_story_5026_50260901_44_dialog_content = "Ah, y debajo de las camas—",
  ui_story_5026_50260901_45_dialog_content = "Eh... Nina... ¿Estás bien?",
  ui_story_5026_50260901_46_dialog_content = "Eso es tan aterrador... ¡Este es el lugar más aterrador en el que he estado en este viaje hasta ahora!",
  ui_story_5026_50260901_47_dialog_content = "¡Es incluso más aterrador que cruzar un puente colgante!",
  ui_story_5026_50260901_48_dialog_content = "Está bien, señorita Nina.",
  ui_story_5026_50260901_49_dialog_content = "Cuando te enfrentas a lo desconocido, lo más importante es obtener toda la información posible.",
  ui_story_5026_50260901_50_dialog_content = "Una vez leí una novela en la que el frío protagonista masculino tenía un arsenal debajo de su cama.",
  ui_story_5026_50260901_51_dialog_content = "Cuando los asesinos se entrometieron en su casa, ¡sacó las armas y protegió a la protagonista femenina!",
  ui_story_5026_50260901_52_dialog_content = "Oh... ¡Yo también he leído ese libro!",
  ui_story_5026_50260901_53_dialog_content = "En otra novela, el protagonista masculino era un holgazán total, pero era leal a la protagonista femenina.",
  ui_story_5026_50260901_54_dialog_content = "Sin embargo, tenía montones de material clasificado R debajo de su cama.",
  ui_story_5026_50260901_55_dialog_content = "¡Así que disfrutas de las novelas románticas! ¿Alguna vez has leído⁠—",
  ui_story_5026_50260901_56_dialog_content = "Sanae... Me voy a ir.",
  ui_story_5026_50260901_57_dialog_content = "nina? ¡Espérame!",
  ui_story_5026_50260901_58_dialog_content = "Es solo talar árboles. Puedo hacerlo por mi cuenta. ¡Solo ven más tarde!",
  ui_story_5026_50260901_59_dialog_content = "La señorita Nina está roja como un tomate. Supongo que no está acostumbrada a este tipo de temas...",
  ui_story_5026_50260901_60_dialog_content = "Sanae, ¿acabas de decir que también leíste \"La seductora de Umbraton\"?",
  ui_story_5026_50260901_61_dialog_content = "No es solo el amor entre los protagonistas, ¡la historia de confianza y traición entre los pandilleros también es muy tentadora!",
  ui_story_5026_50260901_62_dialog_content = "Realmente representa cómo es la vida de las pandillas en Umbraton. ¡Es uno de mis favoritos!",
  ui_story_5026_50260901_63_dialog_content = "¿Qué tal \"La princesa retornada de Lumopolis\"?",
  ui_story_5026_50260901_64_dialog_content = "¡Ay, ese, por supuesto! ¡Me encanta la escena del secuestro de la novia en la boda real!",
  ui_story_5026_50260901_65_dialog_content = "Hice cola durante tanto tiempo solo para comprar la secuela...",
  ui_story_5026_50260901_66_dialog_content = "¡Ay! Um... ¿me emocioné demasiado?",
  ui_story_5026_50260901_67_dialog_content = "¡Está bien! Finalmente encontré a alguien que disfruta lo que yo disfruto. ¡Tengo mucho más que decirte!",
  ui_story_5026_50260901_68_dialog_content = "Nina tenía razón, soy muy habladora cuando encuentro algo de lo que me gusta hablar.",
  ui_story_5026_50260901_69_dialog_content = "Pero lo sé... No es sólo eso.",
  ui_story_5026_50260901_70_dialog_content = "Durante mucho tiempo, pensé que Manae era la única que estaba dispuesta a escucharme hablar.",
  ui_story_5026_50260901_71_dialog_content = "Nina me enseñó que había personas en el mundo que me aceptarían por lo que yo era.",
  ui_story_5026_50260901_72_dialog_content = "Eso debe ser lo que me dio la fuerza para charlar contigo de esta manera.",
  ui_story_5026_50260901_73_dialog_content = "Quiero decir, todavía te debo una gran cantidad de dinero por sacar el barco de Cloud Island...",
  ui_story_5026_50260901_74_dialog_content = "El viejo yo nunca se hubiera atrevido a hablar contigo...",
  ui_story_5026_50260901_75_dialog_content = "Señorita Sana...",
  ui_story_5026_50260901_76_dialog_content = "¡Vaya! ¡Definitivamente trabajaré duro para recuperar el dinero que te debo!",
  ui_story_5026_50260901_77_dialog_content = "Jeje, no hay prisa. Pero basta de negocios...",
  ui_story_5026_50260901_78_dialog_content = "¡Hablemos más sobre \"The Returned Princess of Lumopolis II\"!",
  ui_story_5026_50260902_1_dialog_content = "<color=#e8d9bb>Jardines de Nubes: Bosque</color>",
  ui_story_5026_50260902_2_dialog_content = "No pensé que me encontraría con rezagados de Eclipsite en el camino. Costó más tiempo de lo que pensaba.",
  ui_story_5026_50260902_3_dialog_content = "Gracias por mostrarme el camino.",
  ui_story_5026_50260902_4_dialog_content = "¡Cachero!",
  ui_story_5026_50260902_5_dialog_content = "Parece que prefieren las sombras de los árboles a los pastizales abiertos.",
  ui_story_5026_50260902_6_dialog_content = "La mayoría de los animales tienen miedo de los eclipses. ¿no es así?",
  ui_story_5026_50260902_7_dialog_content = "¿Cachero?",
  ui_story_5026_50260902_8_dialog_content = "Qué extraña criatura. No parece conocer el miedo.",
  ui_story_5026_50260902_9_dialog_content = "Igual que Caelestita.",
  ui_story_5026_50260902_10_dialog_content = "No, tal vez lo encuentro extraño solo porque estoy acostumbrado a Umbraton...",
  ui_story_5026_50260902_11_dialog_content = "Estoy acostumbrado a estar rodeado de personas que usan múltiples máscaras.",
  ui_story_5026_50260902_12_dialog_content = "¡No te preocupes! ¡Te protegeré de cualquier eclipse!",
  ui_story_5026_50260902_13_dialog_content = "Nina! ¡Aqui!",
  ui_story_5026_50260902_14_dialog_content = "¿Cómo está Sanae? Estaba completamente mojada cuando salió del río.",
  ui_story_5026_50260902_15_dialog_content = "Ella esta bien. Bethel está secando su ropa con Luminatics ahora mismo.",
  ui_story_5026_50260902_16_dialog_content = "En tu habitación.",
  ui_story_5026_50260902_17_dialog_content = "¿¡En mi cuarto!?",
  ui_story_5026_50260902_18_dialog_content = "Habitación con toallas! ¡La habitación más cercana! ¡Cachero!",
  ui_story_5026_50260902_19_dialog_content = "¿Tenía que ser mi habitación?",
  ui_story_5026_50260902_20_dialog_content = "PlayerName, debajo de tu cama, ya sabes, um...",
  ui_story_5026_50260902_21_dialog_content = "Oh... Oh no, los encontraste, ¿no?",
  ui_story_5026_50260902_22_dialog_content = "Qu...",
  ui_story_5026_50260902_23_dialog_content = "<size=45>¡Q-Qué desvergonzado!</size>",
  ui_story_5026_50260902_24_dialog_content = "¿De qué estás hablando?",
  ui_story_5026_50260902_25_dialog_content = "¡Es solo una bolsa de sobras de Crunchy Munchy Crunch y una guía ilustrada de la naturaleza a la que le faltan páginas!",
  ui_story_5026_50260902_26_dialog_content = "Tengo que admitir que la habitación está un poco desordenada... Estaba planeando limpiarla antes de que Vice regrese...",
  ui_story_5026_50260902_27_dialog_content = "Qué... Así que eso es...",
  ui_story_5026_50260902_28_option_content = "¿De qué estabas hablando entonces?",
  ui_story_5026_50260902_29_dialog_content = "¡Nada en absoluto!",
  ui_story_5026_50260902_30_option_content = "¿¡Qué otra cosa esperabas!?",
  ui_story_5026_50260902_31_dialog_content = "¿¡C-Cómo podría saberlo!?",
  ui_story_5026_50260902_32_dialog_content = "No importa esos asuntos tontos. ¿De qué hablaron Minos y tú en el río?",
  ui_story_5026_50260902_33_dialog_content = "Bueno... Solo que eres la hija del Conde Andersen, y como te escapaste de casa.",
  ui_story_5026_50260902_34_dialog_content = "Lo sabía.",
  ui_story_5026_50260902_35_dialog_content = "¿Te ofreció pagarte lo que quisieras por no contratarme?",
  ui_story_5026_50260902_36_dialog_content = "Seguro que me gustaría un cheque que pague todas mis deudas...",
  ui_story_5026_50260902_37_dialog_content = "¿Así que aceptaste la oferta?",
  ui_story_5026_50260902_38_dialog_content = "¡No! ¡Por supuesto que no! Sólo bromeaba.",
  ui_story_5026_50260902_39_dialog_content = "Por cierto, ¿no fue bueno que todo en tu tienda estuviera agotado?",
  ui_story_5026_50260902_40_dialog_content = "Quiero decir, la gente abre una tienda para ganar dinero, ¿no?",
  ui_story_5026_50260902_41_dialog_content = "Ni siquiera sé cuál de tus palabras encuentro más impactante...",
  ui_story_5026_50260902_42_dialog_content = "Bueno... Eraveil rara vez comerciaba con el mundo exterior, y Soroz no tenía mucho que enseñarme al respecto.",
  ui_story_5026_50260902_43_dialog_content = "No importa. Soportaré tu ignorancia ya que eres un socio comercial importante.",
  ui_story_5026_50260902_44_dialog_content = "Para mí, no se trata sólo del dinero.",
  ui_story_5026_50260902_45_dialog_content = "Probablemente pienses que soy una princesa que no sabe cómo es la vida para la mayoría.",
  ui_story_5026_50260902_46_dialog_content = "Por supuesto, sé que hacer que un negocio sea rentable no es poca cosa.",
  ui_story_5026_50260902_47_dialog_content = "Pero lo que quiero es que mis diseños ganen la validación de la gente.",
  ui_story_5026_50260902_48_dialog_content = "A mi padre le preocupaba que me enojara si mis cosas no se vendían, por eso compró todo.",
  ui_story_5026_50260902_49_dialog_content = "Incluso si eso me molestara, habría aceptado el resultado sabiendo que hice lo mejor que pude.",
  ui_story_5026_50260902_50_dialog_content = "¿Sabías que Bethel se convirtió en la mano derecha del Señor de las Sombras cuando no era mucho mayor que yo?",
  ui_story_5026_50260902_51_dialog_content = "Entonces, ¿su objetivo es superar a Bethel y ser el principal comerciante de Umbraton?",
  ui_story_5026_50260902_52_dialog_content = "Tch... los aficionados pueden ser tan simples.",
  ui_story_5026_50260902_53_dialog_content = "No importa. No me sorprende que pienses de esa manera.",
  ui_story_5026_50260902_54_dialog_content = "Claro, la gente a menudo me comparaba con ella en los muchos eventos sociales de Umbraton.",
  ui_story_5026_50260902_55_dialog_content = "Ella es increíble a su manera, pero abrí mis tiendas porque quería seguir mis pasiones.",
  ui_story_5026_50260902_56_dialog_content = "Pero no se dejen engañar, de lo que ella sea capaz, ¡algún día yo también podré hacerlo!",
  ui_story_5026_50260902_57_dialog_content = "¡O-Por mi cuenta, por supuesto, sin depender de mi padre ni de nadie más!",
  ui_story_5026_50260902_58_dialog_content = "(Aunque no lo admita, todavía se compara con Bethel).",
  ui_story_5026_50260902_59_dialog_content = "Sin depender de nadie... hmm.",
  ui_story_5026_50260902_60_dialog_content = "Nina.",
  ui_story_5026_50260902_61_dialog_content = "¿Eh? ¿Qué pasa con la repentina seriedad?",
  ui_story_5026_50260902_62_dialog_content = "Nunca he conocido a mis padres excepto en mis sueños.",
  ui_story_5026_50260902_63_dialog_content = "Como el último Caelestita que quedó en este continente, siempre estuve solo.",
  ui_story_5026_50260902_64_dialog_content = "Solía pensar que esperaría el final con Soroz bajo tierra.",
  ui_story_5026_50260902_65_dialog_content = "Pero entonces, un día, Vice cayó del cielo y me llevó a un mundo completamente nuevo.",
  ui_story_5026_50260902_66_dialog_content = "Hice muchos amigos a lo largo de nuestro viaje y experimenté aventuras increíbles.",
  ui_story_5026_50260902_67_dialog_content = "Cuando estaba indefenso y solo, me dieron mucho apoyo.",
  ui_story_5026_50260902_68_dialog_content = "Sin ellos, no estaría parado aquí ahora.",
  ui_story_5026_50260902_69_dialog_content = "¿Nunca peleaste con ellos antes?",
  ui_story_5026_50260902_70_dialog_content = "Claro que lo hicimos, pero al final, siempre llegamos a un acuerdo.",
  ui_story_5026_50260902_71_dialog_content = "Seríamos comunicativos si no nos gustara lo que el otro estaba haciendo.",
  ui_story_5026_50260902_72_dialog_content = "Comuníquese con las personas que le importan mientras todavía están cerca. No digas cosas de las que luego te arrepentirás.",
  ui_story_5026_50260902_73_dialog_content = "No planeas no volver nunca a casa, solo porque estás enojado con tu padre, ¿verdad?",
  ui_story_5026_50260902_74_dialog_content = "O-Claro que no...",
  ui_story_5026_50260902_75_dialog_content = "Si pudieras decirle lo que acabas de decirme hoy...",
  ui_story_5026_50260902_76_dialog_content = "Estoy seguro de que lo entendería, y nunca volvería a cometer el mismo error.",
  ui_story_5026_50260902_77_dialog_content = "(Es un hombre que se cierra al mundo solo porque su hija está enojada con él...)",
  ui_story_5026_50260902_78_dialog_content = "¿Intentaste hablar con tu padre antes de huir de casa?",
  ui_story_5026_50260902_79_dialog_content = "...",
  ui_story_5026_50260902_80_dialog_content = "¿Hablale? ... Entiendo.",
  ui_story_5026_50260902_81_dialog_content = "Pero antes de eso, quiero lograr lo que me propuse lograr.",
  ui_story_5026_50260902_82_dialog_content = "¡Esa es la única forma de demostrarle que no necesito depender de él para lograr cosas!",
  ui_story_5026_50260902_83_dialog_content = "Hemos patrullado todos los Jardines de las Nubes, ¿verdad?",
  ui_story_5026_50260902_84_dialog_content = "Sí, hemos exterminado a todos los eclipses que encontramos.",
  ui_story_5026_50260902_85_dialog_content = "Ahora que ya está hecho, las operaciones comerciales son las siguientes en la lista.",
  ui_story_5026_50260902_86_dialog_content = "Pensé en convertir este lugar en un resort idílico y ganar mi fajo de dinero con las tarifas de admisión y alojamiento.",
  ui_story_5026_50260902_87_dialog_content = "¿Tarifas de alojamiento? Todos aquí son mis amigos, yo nunca—",
  ui_story_5026_50260902_88_dialog_content = "Luego, desarrollar el terreno circundante, convirtiéndolo en el corazón de una gran red logística que abarca todo el continente.",
  ui_story_5026_50260902_89_dialog_content = "¿Qué es una... red logística?",
  ui_story_5026_50260902_90_dialog_content = "Y luego usar el fascinante Colossus, que es mucho más avanzado que cualquier tecnología auroriana, para transportar mercancías.",
  ui_story_5026_50260902_91_dialog_content = "No debería ser difícil para alguien tan famoso como tú conseguir pedidos, ¿verdad? PlayerName?",
  ui_story_5026_50260902_92_dialog_content = "No creo que tengan mucho que ver conmigo...",
  ui_story_5026_50260902_93_dialog_content = "Hay negocios en todas partes con todos, PlayerName. En última instancia, se trata de lo que se vende.",
  ui_story_5026_50260902_94_dialog_content = "Incluso los grandes clientes autosuficientes que no hacen negocios con los gremios de Umbraton...",
  ui_story_5026_50260902_95_dialog_content = "No dudaría en intentar construir una relación con Last Caelestite.",
  ui_story_5026_50260902_96_dialog_content = "No sería descabellado pensar que toda la economía de Astra algún día podría estar al alcance de nuestras manos...",
  ui_story_5026_50260902_97_dialog_content = "Eso es realmente descabellado...",
  ui_story_5026_50260902_98_dialog_content = "Pero tal es el plan de dominación mundial que he hecho para ti.",
  ui_story_5026_50260902_99_dialog_content = "\"Ahora bien, deberíamos empezar\".",
  ui_story_5026_50260902_100_dialog_content = "Eso es lo que quería decir, pero puedo ver que tienes algo más en mente.",
  ui_story_5026_50260902_101_dialog_content = "Tal como dijiste, es importante comunicarse.",
  ui_story_5026_50260902_102_dialog_content = "Especialmente si somos socios comerciales interdependientes. Así que continúa, di tu parte.",
  ui_story_5026_50260902_103_dialog_content = "Que pienso...",
  ui_story_5026_50260902_104_dialog_content = "(¿Qué tipo de lugar quiero que sea Cloud Gardens después de eliminar todos los Eclipsites?)",
  ui_story_5026_50260902_105_dialog_content = "(Después de peinar cada centímetro de este lugar con mis propios ojos...)",
  ui_story_5026_50260902_106_dialog_content = "Yo...",
  ui_story_5026_50260902_107_dialog_content = "Lamento interrumpir, Srta. Nina, Sr. Navegante.",
  ui_story_5026_50260902_108_dialog_content = "Pero hay algo que necesito informar a PlayerName.",
  ui_story_5026_50260902_109_dialog_content = "No había señales de eclipses mientras recogíamos madera, pero ahora...",
  ui_story_5026_50260902_110_dialog_content = "Un grupo de ellos se está acercando desde el bosque más adelante.",
  ui_story_5026_50261001_1_dialog_content = "Uf... Esa debería ser la última.",
  ui_story_5026_50261001_2_dialog_content = "¿PlayerName?",
  ui_story_5026_50261001_3_dialog_content = "Que esta pasando...?",
  ui_story_5026_50261001_4_dialog_content = "Puedo sentir Darkflow rodeando Cloud Gardens...",
  ui_story_5026_50261001_5_dialog_content = "¿Mi habilidad se volvió loca?",
  ui_story_5026_50261001_6_dialog_content = "¡Algo malo está pasando!",
  ui_story_5026_50261001_7_dialog_content = "¿Qué paso?",
  ui_story_5026_50261001_8_dialog_content = "Después de que salimos del dormitorio para reunirnos contigo, vimos...",
  ui_story_5026_50261001_9_dialog_content = "Tienes que verlo con tus propios ojos para creerlo. ¡Ven, te lo mostraré!",
  ui_story_5026_50261001_10_dialog_content = "Qué está pasando... Acabamos de limpiar este lugar de todos los eclipses, ¿no?",
  ui_story_5026_50261001_11_dialog_content = "Primero pensé que los eclipses encontrados aquí eran solo unos pocos rezagados...",
  ui_story_5026_50261001_12_dialog_content = "Luego, en mi patrulla por Cloud Gardens, me di cuenta de que probablemente no era tan simple.",
  ui_story_5026_50261001_13_dialog_content = "Y ahora...",
  ui_story_5026_50261001_14_dialog_content = "Realmente soy demasiado ingenuo.",
  ui_story_5026_50261001_15_dialog_content = "S-Solo tenemos que expulsarlos, ¿verdad?",
  ui_story_5026_50261001_16_dialog_content = "Ya me siento mal por no pagarte durante tu libertad condicional...",
  ui_story_5026_50261001_17_dialog_content = "Pero esta crisis ha superado con creces mis expectativas.",
  ui_story_5026_50261001_18_dialog_content = "Umbraton definitivamente contrataría mercenarios permanentes si una de sus ciudades encontrara tantos Eclipses.",
  ui_story_5026_50261001_19_dialog_content = "Sin embargo, esto sin duda generaría costos adicionales.",
  ui_story_5026_50261001_20_dialog_content = "No quiero estar ya acumulando deudas cuando Cloud Gardens recién comienza a desarrollarse, pero parece que no me queda otra opción...",
  ui_story_5026_50261001_21_dialog_content = "Volveré a Umbraton y me pondré en contacto con los mercenarios registrados en el cuartel general del gremio.",
  ui_story_5026_50261001_22_dialog_content = "Será más rápido volar el Colossus, pero probablemente no quieras dejar Cloud Gardens así, ¿verdad? PlayerName?",
  ui_story_5026_50261001_23_dialog_content = "Sé que tienes un presupuesto limitado, ¡así que haré todo lo posible para conseguirte descuentos!",
  ui_story_5026_50261001_24_dialog_content = "Qué debemos hacer ahora, PlayerName?",
  ui_story_5026_50261001_25_dialog_content = "Los Eclipsites no parecen habernos descubierto todavía.",
  ui_story_5026_50261001_26_dialog_content = "Hmm... No parecen moverse con ningún propósito.",
  ui_story_5026_50261001_27_dialog_content = "Al menos, eso significa que no es un ataque ordenado por un Eclipsite de alto nivel.",
  ui_story_5026_50261001_28_dialog_content = "Probablemente no tengamos tanta suerte la próxima vez si no encontramos una solución sostenible a largo plazo.",
  ui_story_5026_50261001_29_dialog_content = "Sentí menos actividades de Eclipsite alrededor de Hyacinth Tower. Vamos a esperar allí a que regrese Bethel.",
  ui_story_5026_50261201_1_dialog_content = "(El Obelisco del Retorno definitivamente expulsó a todos los Eclipsites presentes en Eraveil en ese momento...)",
  ui_story_5026_50261201_2_dialog_content = "(Entonces estos eclipses deben haber venido de otros lugares).",
  ui_story_5026_50261201_3_dialog_content = "(Nina tenía razón... La paz es rara y preciosa...)",
  ui_story_5026_50261201_4_dialog_content = "(¡Ni siquiera quiero saber lo caro que puede ser contratar mercenarios de Umbraton a largo plazo!)",
  ui_story_5026_50261201_5_dialog_content = "Ahí tienes, PlayerName.",
  ui_story_5026_50261201_6_dialog_content = "...",
  ui_story_5026_50261201_7_dialog_content = "Oye, PlayerName!",
  ui_story_5026_50261201_8_dialog_content = "Nina...?",
  ui_story_5026_50261201_9_dialog_content = "¡N-no vine porque estaba preocupada o algo así!",
  ui_story_5026_50261201_10_dialog_content = "¡Es solo que no puedo dejar que tu estado de ánimo desanimado afecte el negocio!",
  ui_story_5026_50261201_11_dialog_content = "¡Eso es todo!",
  ui_story_5026_50261201_12_dialog_content = "Así que estás aquí porque te importa.",
  ui_story_5026_50261201_13_dialog_content = "Ugh... si tienes que decirlo de esa manera, supongo que no es del todo inexacto.",
  ui_story_5026_50261201_14_dialog_content = "Minos y Sanae vigilan. Ningún eclipse se acercará.",
  ui_story_5026_50261201_15_dialog_content = "De todos modos, vamos a sentarnos allí.",
  ui_story_5026_50261201_16_dialog_content = "¿Por qué pareces tener más cosas en mente que yo?",
  ui_story_5026_50261201_17_dialog_content = "Minos me llevará de regreso a Umbraton pronto.",
  ui_story_5026_50261201_18_dialog_content = "Hice una apuesta con él. Si le ganaba en una sola cosa, me dejaría en paz.",
  ui_story_5026_50261201_19_dialog_content = "No tuviste oportunidad.",
  ui_story_5026_50261201_20_dialog_content = "¡C-cállate!",
  ui_story_5026_50261201_21_dialog_content = "Yo... debería haber sabido que Minos no habría estado de acuerdo si no estuviera seguro de que ganaría.",
  ui_story_5026_50261201_22_dialog_content = "Ya sea plantando árboles únicos, excavando en busca de tesoros o pescando...",
  ui_story_5026_50261201_23_dialog_content = "También perdí el último, ¿no?",
  ui_story_5026_50261201_24_dialog_content = "Si estamos haciendo comparaciones...",
  ui_story_5026_50261201_25_dialog_content = "Minos clasificó la madera que reunió e incluso anotó el mejor uso para cada tipo.",
  ui_story_5026_50261201_26_dialog_content = "Aparentemente, también usó un método llamado \"tala selectiva\" para asegurarse de que los árboles restantes crecieran mejor.",
  ui_story_5026_50261201_27_dialog_content = "Siempre corté el árbol que estaba más cerca de mí... Ni siquiera sabía que existía tal método.",
  ui_story_5026_50261201_28_dialog_content = "Eso significa que no importaba cuánta madera recogiéramos Sanae y yo... Estábamos destinados a perder desde el principio.",
  ui_story_5026_50261201_29_dialog_content = "Bueno... Como nuestro mayordomo, es de esperar tanta habilidad.",
  ui_story_5026_50261201_30_dialog_content = "¿Lo estás alabando?",
  ui_story_5026_50261201_31_dialog_content = "Solo reconozco mis fracasos y digo la verdad.",
  ui_story_5026_50261201_32_dialog_content = "Pero como ya sabrás, su objetivo es llevarme a casa.",
  ui_story_5026_50261201_33_dialog_content = "Al final, todavía no tienes a nadie adecuado para administrar Cloud Gardens.",
  ui_story_5026_50261201_34_dialog_content = "No tienes que preocuparte por eso.",
  ui_story_5026_50261201_35_dialog_content = "Puede sonar increíble, pero Minos dijo...",
  ui_story_5026_50261201_36_dialog_content = "Mientras realizaba las tareas diarias, logró enseñar a los Chubb Farmers cómo trabajar como él.",
  ui_story_5026_50261201_37_dialog_content = "Entonces por eso lo llamaban \"Maestro\".",
  ui_story_5026_50261201_38_dialog_content = "Dice que a pesar de estar limitados por su naturaleza, siguen siendo buenos aprendices.",
  ui_story_5026_50261201_39_dialog_content = "Como mínimo, bajo su cuidado, no debería haber ningún Árbol Único que no crezca.",
  ui_story_5026_50261201_40_dialog_content = "Contratar a un mayordomo como Minos probablemente esté fuera de mi presupuesto de todos modos...",
  ui_story_5026_50261201_41_dialog_content = "Ni siquiera sabía que se las había arreglado para hacer eso... Tch, como si derrotarme no fuera suficiente.",
  ui_story_5026_50261201_42_dialog_content = "Pero... Estaba pensando que tal vez fue un poco imprudente huir de casa de esa manera.",
  ui_story_5026_50261201_43_dialog_content = "¡N-Tú no fuiste quien puso la idea en mi cabeza!",
  ui_story_5026_50261201_44_dialog_content = "Todavía estoy enojado con mi padre por lo que hizo, y Minos por ponerse del lado de Padre todo el tiempo.",
  ui_story_5026_50261201_45_dialog_content = "Pero estoy más molesto conmigo mismo.",
  ui_story_5026_50261201_46_dialog_content = "Qué arrogante soy al estipular un gran plan de negocios para ti cuando ni siquiera puedo lidiar con el problema de Eclipsite.",
  ui_story_5026_50261201_47_dialog_content = "Y arruiné totalmente el trabajo de plantar árboles... Estoy lejos de ser la persona que dije que iba a ser.",
  ui_story_5026_50261201_48_dialog_content = "No estropeaste nada... aunque no fue genial...",
  ui_story_5026_50261201_49_dialog_content = "¿Mmm? ¿A qué te refieres?",
  ui_story_5026_50261201_50_dialog_content = "¡Nada! ¡Creo que tu gran plan de negocios es genial! ¡Es bastante creativo e imaginativo!",
  ui_story_5026_50261201_51_dialog_content = "Je... No podría haber peor crítica para un plan de negocios.",
  ui_story_5026_50261201_52_dialog_content = "Admito que hay muchas cosas que necesito resolver, como cuestiones geográficas y de transporte, sin mencionar...",
  ui_story_5026_50261201_53_dialog_content = "Un gran centro de negocios necesita cafés, restaurantes y parques de diversiones, ¡al igual que Umbraton!",
  ui_story_5026_50261201_54_dialog_content = "Hmm... ¿Cómo debería decirlo?",
  ui_story_5026_50261201_55_dialog_content = "Realmente no veo que Cloud Gardens se convierta en un centro de negocios...",
  ui_story_5026_50261201_56_dialog_content = "Tampoco me imagino a Soroz siendo una herramienta de negocio.",
  ui_story_5026_50261201_57_dialog_content = "Soroz tiene una mente propia.",
  ui_story_5026_50261201_58_dialog_content = "Al menos... alguna vez lo hizo. Me elevó.",
  ui_story_5026_50261201_59_dialog_content = "Durante mucho tiempo me enseñó todo lo que sé sobre los Caelestites.",
  ui_story_5026_50261201_60_dialog_content = "(¿Qué diría si me viera ahora...?)",
  ui_story_5026_50261201_61_dialog_content = "Ya veo. Me disculpo por no ser lo suficientemente considerado.",
  ui_story_5026_50261201_62_dialog_content = "Entonces, dime lo que tienes en mente.",
  ui_story_5026_50261201_63_dialog_content = "¿Qué?",
  ui_story_5026_50261201_64_dialog_content = "¿En qué quieres que se convierta Cloud Gardens?",
  ui_story_5026_50261201_65_dialog_content = "...",
  ui_story_5026_50261201_66_dialog_content = "En Eraveil, una Caelestite una vez desertó a los Eclipsites para ganar poder a costa de toda mi raza.",
  ui_story_5026_50261201_67_dialog_content = "El método que usó para buscar el poder estaba completamente equivocado, no se puede negar eso.",
  ui_story_5026_50261201_68_dialog_content = "Pero he estado pensando...",
  ui_story_5026_50261201_69_dialog_content = "¿Hubo otras cosas que la llevaron por ese camino además de la arrogancia y la cobardía?",
  ui_story_5026_50261201_70_dialog_content = "Todavía no sé la historia completa. Todo lo que sé son fragmentos.",
  ui_story_5026_50261201_71_dialog_content = "Solo sé que incluso al final, no obtuvo la paz y la tranquilidad que quería.",
  ui_story_5026_50261201_72_dialog_content = "Así que... quiero hacer de este lugar un refugio de paz y serenidad para todos.",
  ui_story_5026_50261201_73_dialog_content = "Un lugar diferente al Eraveil que perteneció a mis antepasados.",
  ui_story_5026_50261201_74_dialog_content = "PlayerName.",
  ui_story_5026_50261201_75_dialog_content = "Lo pones bien. Incluso yo estoy un poco… no, estoy muy conmovido por tus palabras.",
  ui_story_5026_50261201_76_dialog_content = "Pero, necesito detalles. ¿Qué piensas construir aquí?",
  ui_story_5026_50261201_77_dialog_content = "Eres tan pragmático... Creo que tuve una conversación similar con Bethel antes.",
  ui_story_5026_50261201_78_dialog_content = "Se llama ser práctico. Será mejor que te acostumbres a cómo hacemos las cosas en Umbraton.",
  ui_story_5026_50261201_79_dialog_content = "De acuerdo con lo que Bethel escribió en el aviso de contratación, obtener ganancias es imprescindible, ¿no es así?",
  ui_story_5026_50261201_80_dialog_content = "Sí... Quién diría que la información de Sheol sería tan cara...",
  ui_story_5026_50261201_81_dialog_content = "Subestimar el valor de una pieza de inteligencia... Qué novato.",
  ui_story_5026_50261201_82_dialog_content = "¿Hay alguna forma de ganar mucho Nightium a la vez, como ganar la lotería?",
  ui_story_5026_50261201_83_dialog_content = "PlayerName, sabes algo de negocios grises?",
  ui_story_5026_50261201_84_dialog_content = "Suena incompleto...",
  ui_story_5026_50261201_85_dialog_content = "Beneficio masivo a corto plazo de fuentes desconocidas. Muchos gremios en Umbraton tienen esos recursos...",
  ui_story_5026_50261201_86_dialog_content = "Incluidos los Andersens, antes de que mi padre se hiciera cargo.",
  ui_story_5026_50261201_87_dialog_content = "¿Acabo de escuchar algo que no debería haber escuchado?",
  ui_story_5026_50261201_88_dialog_content = "No te estoy pidiendo que hagas lo mismo, solo lo mencioné como una opción.",
  ui_story_5026_50261201_89_dialog_content = "¿Cómo puede alguien estar tranquilo ganando dinero sin saber de dónde viene, especialmente considerando que alguien podría haber resultado perjudicado en el proceso?",
  ui_story_5026_50261201_90_dialog_content = "Los demás no sé, pero a mi padre le llegaron como herencia.",
  ui_story_5026_50261201_91_dialog_content = "A pesar de que sacó a nuestra familia de negocios tan turbios, no pudo hacer nada con respecto a un legado pasado sobre el que no tenía control.",
  ui_story_5026_50261201_92_dialog_content = "Sin embargo, pudo decidir cómo utilizar esa herencia.",
  ui_story_5026_50261201_93_dialog_content = "Una vez me dijo algo después de que visitáramos las clínicas y los orfanatos financiados por los Andersen.",
  ui_story_5026_50261201_94_dialog_content = "\"El pasado está en el pasado. Hoy y mañana, sin embargo, todavía están en nuestras manos\".",
  ui_story_5026_50261201_95_dialog_content = "Algunos en Umbraton consideran la piedad caritativa de los ricos, la arrogancia de un noble en declive, o incluso el veneno de una víbora disfrazado...",
  ui_story_5026_50261201_96_dialog_content = "¡Hmph! ¡Tal vez piensen que pueden ascender a Lumopolis en su escala de marfil de moralidad!",
  ui_story_5026_50261201_97_dialog_content = "Pero he visto con mis propios ojos cuantos se beneficiaron de la herencia.",
  ui_story_5026_50261201_98_dialog_content = "Me pregunto si Padre se ha estado cuidando mientras yo no estaba...",
  ui_story_5026_50261201_99_dialog_content = "Si estuviera aquí, podría darte mejores consejos. PlayerName.",
  ui_story_5026_50261201_100_dialog_content = "Estoy divagando... De todos modos...",
  ui_story_5026_50261201_101_dialog_content = "Nina, en realidad amas mucho a tu padre, ¿no?",
  ui_story_5026_50261201_102_dialog_content = "¿¡Qué te dio esa idea!? Multa. Es mi culpa por desviarme del tema primero...",
  ui_story_5026_50261201_103_dialog_content = "Realmente no lo llamaría divagación.",
  ui_story_5026_50261201_104_dialog_content = "Cloud Gardens y los Chubbs son... mi herencia, por así decirlo.",
  ui_story_5026_50261201_105_dialog_content = "Pero por una miríada de razones, no he podido prestarle mucha atención hasta ahora.",
  ui_story_5026_50261201_106_dialog_content = "Tal vez haya alguna ganancia inesperada de todo esto...",
  ui_story_5026_50261201_107_dialog_content = "<size=45>¡Estoy de acuerdo!</size>",
  ui_story_5026_50261201_108_dialog_content = "¿Cómo?",
  ui_story_5026_50261201_109_dialog_content = "¡No le prestas suficiente atención a los Chubbs!",
  ui_story_5026_50261201_110_dialog_content = "Incluso si estoy más acostumbrado a notar detalles en las apariencias físicas, siendo diseñador y todo...",
  ui_story_5026_50261201_111_dialog_content = "¿Cómo no puedes notar la diferencia entre los Chubbs?",
  ui_story_5026_50261201_112_dialog_content = "Incluso si no puedes saberlo con solo mirarlos, según Sanae, también tienen personalidades diferentes.",
  ui_story_5026_50261201_113_dialog_content = "¿Diferentes personalidades? ¿En serio?",
  ui_story_5026_50261201_114_dialog_content = "Sanae sintió pena por pensar que eran iguales, así que les prestó más atención.",
  ui_story_5026_50261201_115_dialog_content = "Pero no deberías necesitar ser tan observador como ella para decirlo. Quiero decir, ya deberías saber eso después de pasar tanto tiempo con ellos.",
  ui_story_5026_50261201_116_dialog_content = "PlayerName, ¿ha pensado alguna vez en capacitar periódicamente a sus empleados?",
  ui_story_5026_50261201_117_dialog_content = "¿O trabajar con ellos para resolver los problemas que encuentra al administrar el negocio?",
  ui_story_5026_50261201_118_dialog_content = "Aunque... no hay nada de qué hablar si no nos deshacemos primero de los Eclipsites...",
  ui_story_5026_50261201_119_dialog_content = "Te vuelves tan aterrador tan pronto como empiezas a hablar de asuntos de negocios...",
  ui_story_5026_50261201_120_dialog_content = "<size=45>¡C-cállate!</size> ¡Estoy tratando de ayudarte!",
  ui_story_5026_50261201_121_dialog_content = "Lo sé, y te lo agradezco, Nina.",
  ui_story_5026_50261201_122_dialog_content = "Gracias a lo que dijiste antes, en realidad pensé en algo. Por supuesto, necesito probarlo primero.",
  ui_story_5026_50261201_123_dialog_content = "Voy a tratar de actuar como el Maestro de Cloud Gardens...",
  ui_story_5026_50261201_124_dialog_content = "Un método Caelestite.",
  ui_story_5026_50261301_1_dialog_content = "¿Qué estás buscando en los arbustos? No creo que haya nada ahí.",
  ui_story_5026_50261301_2_dialog_content = "¿Qué tipo de método Caelestite es este?",
  ui_story_5026_50261301_3_dialog_content = "Lo sabía. Estas ruinas son exactamente iguales a los edificios que restauré usando los planos.",
  ui_story_5026_50261301_4_dialog_content = "Dormitorios, pozos... Por lo que parece, Cloud Gardens definitivamente solía ser una gran área residencial.",
  ui_story_5026_50261301_5_dialog_content = "Pero, hay muy pocas señales de puestos de vigilancia.",
  ui_story_5026_50261301_6_dialog_content = "Dado que las medidas defensivas en el Obelisco del Retorno son muy difíciles de activar...",
  ui_story_5026_50261301_7_dialog_content = "Es probable que Cloud Gardens tenga su propio conjunto de medidas defensivas automatizadas.",
  ui_story_5026_50261301_8_dialog_content = "Nada mal, PlayerName!",
  ui_story_5026_50261301_9_option_content = "¿Impresionado?",
  ui_story_5026_50261301_10_dialog_content = "J-Solo un poco.",
  ui_story_5026_50261301_11_option_content = "Jeje.",
  ui_story_5026_50261301_12_dialog_content = "No estés demasiado lleno de ti mismo.",
  ui_story_5026_50261301_13_dialog_content = "No pensé que estudiar esos planos sería tan útil.",
  ui_story_5026_50261301_14_dialog_content = "Eso me recuerda... Tal vez sepa sobre las medidas defensivas.",
  ui_story_5026_50261301_15_dialog_content = "<anim type=Shake>Buf, buf...</anim>",
  ui_story_5026_50261301_16_dialog_content = "¡Despierta! ¡Despierta!",
  ui_story_5026_50261301_17_dialog_content = "Un Chubb con bigote largo... se ve esponjoso.",
  ui_story_5026_50261301_18_dialog_content = "¡Oh, es el Maestro! ¿Encontraste nuevos planos, Chubb?",
  ui_story_5026_50261301_19_dialog_content = "No estoy aquí por los planos de hoy.",
  ui_story_5026_50261301_20_dialog_content = "Quiero saber si hay algún sistema de defensa aquí en Cloud Gardens.",
  ui_story_5026_50261301_21_dialog_content = "Por supuesto. Cachero.",
  ui_story_5026_50261301_22_dialog_content = "¡¿En realidad?! ¿Por qué no me dijiste antes?",
  ui_story_5026_50261301_23_dialog_content = "El Maestro no preguntó antes, Chubb.",
  ui_story_5026_50261301_24_dialog_content = "¡Algo así de importante debería habérseme dicho antes de enseñarme a plantar árboles!",
  ui_story_5026_50261301_25_dialog_content = "No entiendo. ¿Vuelve, Chubb?",
  ui_story_5026_50261301_26_dialog_content = "(De repente recuerdo lo frustrante que fue tratar de hablar con Neural Aux en el Obelisco del Retorno...)",
  ui_story_5026_50261301_27_dialog_content = "¿Cómo activo este sistema de defensa?",
  ui_story_5026_50261301_28_dialog_content = "Puede activar o desactivar el sistema de defensa objetivo desde la terminal de control en Hyacinth Tower, Chubb.",
  ui_story_5026_50261301_29_dialog_content = "¿Cómo llego a la terminal de control?",
  ui_story_5026_50261301_30_dialog_content = "Información confidencial accedida. Cambiar el modo de interacción. Verificando acceso...",
  ui_story_5026_50261301_31_dialog_content = "Objetivo: PlayerName, la Última Caelestita.",
  ui_story_5026_50261301_32_dialog_content = "Verificando código de clase \"Defensor\"... Verificación fallida.",
  ui_story_5026_50261301_33_dialog_content = "Terminando el proceso de verificación...",
  ui_story_5026_50261301_34_dialog_content = "Máximo Decreto verificado.",
  ui_story_5026_50261301_35_dialog_content = "PlayerNameLas órdenes de deben ser seguidas, PlayerNameLos deseos de 's llevados a cabo.",
  ui_story_5026_50261301_36_dialog_content = "Acceso verificado. Información confidencial desbloqueada.",
  ui_story_5026_50261301_37_dialog_content = "PlayerName la Caelestita.",
  ui_story_5026_50261301_38_dialog_content = "¡Sí! ¡Estoy aquí!",
  ui_story_5026_50261301_39_dialog_content = "De repente se siente como si estuviéramos hablando con un anciano...",
  ui_story_5026_50261301_40_dialog_content = "Para dar la vuelta al banco de trabajo y acceder a la terminal de control, debe conectarse mentalmente con cuatro o más Chubbs y sintetizar la clave secreta.",
  ui_story_5026_50261301_41_dialog_content = "Información confidencial transmitida. Cambiar el modo de interacción.",
  ui_story_5026_50261301_42_dialog_content = "A-¿Algo más?",
  ui_story_5026_50261301_43_dialog_content = "<anim type=Shake>Ronquido...</anim>",
  ui_story_5026_50261301_44_dialog_content = "<size=45>¡Se quedó dormido!</size>",
  ui_story_5026_50261301_45_dialog_content = "El banco de trabajo debe ser lo que uso para hacer muebles... ¿Entonces el terminal de control está debajo?",
  ui_story_5026_50261301_46_dialog_content = "Lo golpeé bastante fuerte la última vez cuando estaba haciendo una mesa... Espero no haberlo dañado.",
  ui_story_5026_50261301_47_dialog_content = "En lugar de preocuparte por eso, ¿por qué no vas y buscas tres Chubbs más primero?",
  ui_story_5026_50261301_48_dialog_content = "Derecha. Probablemente habrá algunas batallas en el camino.",
  ui_story_5026_50261301_49_dialog_content = "Supongo que tendré que ayudarte una vez más. No importa con qué eclipses nos encontremos, yo...",
  ui_story_5026_50261301_50_dialog_content = "¡Quiero decir, Sanae y yo y todos, te protegeremos!",
  ui_story_5026_50261301_51_dialog_content = "Solo haz honor a tu papel como comandante. ¡No me detengas!",
  ui_story_5026_50261402_1_dialog_content = "¡Ja! Aquí funciona, ¿verdad?",
  ui_story_5026_50261402_2_dialog_content = "Ahora tenemos todos los Chubbs que necesitamos.",
  ui_story_5026_50261402_3_dialog_content = "Pero quiero que me retengan un poco más, Chubb.",
  ui_story_5026_50261402_4_dialog_content = "Hmm... Entonces, ¿qué tal si yo...?",
  ui_story_5026_50261402_5_dialog_content = "Sanae, solo ignóralo.",
  ui_story_5026_50261402_6_dialog_content = "(Estoy empezando a entender lo que Sanae quiso decir con que tenían personalidades diferentes...)",
  ui_story_5026_50261402_7_dialog_content = "(Y solo entre estos cuatro Chubbs, puedo distinguirlos por su apariencia).",
  ui_story_5026_50261402_8_dialog_content = "Entonces, ¿qué debo hacer es vincularme mentalmente con ellos para sintetizar la Clave secreta? ¿Eso es todo?",
  ui_story_5026_50261402_9_dialog_content = "Si lo desea, puede comenzar a vincularse a los Chubbs en orden.",
  ui_story_5026_50261402_10_dialog_content = "¿En orden?",
  ui_story_5026_50261402_11_dialog_content = "Chubb Scholar es tercero, Chubb.",
  ui_story_5026_50261402_12_dialog_content = "Y el élder Chubb es el segundo, Chubb.",
  ui_story_5026_50261402_13_dialog_content = "Bien entonces...",
  ui_story_5026_50261402_14_dialog_content = "Chubb Merchant debería ser tercero, Chubb.",
  ui_story_5026_50261402_15_dialog_content = "Espera, ¿qué?",
  ui_story_5026_50261402_16_dialog_content = "Chubb Merchant cree que Chubb Scholar es el primero, Chubb.",
  ui_story_5026_50261402_17_dialog_content = "Chubb Farmer es el primero, Chubb.",
  ui_story_5026_50261402_18_dialog_content = "Chubb Farmer recuerda que se supone que el anciano Chubb es el cuarto, Chubb.",
  ui_story_5026_50261402_19_dialog_content = "Incluso estás actuando como si estuvieras bien informado...",
  ui_story_5026_50261402_20_dialog_content = "¿No pueden decirme la secuencia? El élder Chubb debe estar seguro, ¿verdad?",
  ui_story_5026_50261402_21_dialog_content = "Soy viejo y no me acuerdo, Chubb.",
  ui_story_5026_50261402_22_dialog_content = "<size=45>¡Tu memoria estaba perfectamente bien hace un momento!</size>",
  ui_story_5026_50261402_23_dialog_content = "Pero sé que sus palabras son mitad correctas y mitad incorrectas, Chubb.",
  ui_story_5026_50261402_24_dialog_content = "Entonces... No puedo vincularme con éxito a menos que reciba el pedido, ¿verdad?",
  ui_story_5026_50261402_25_dialog_content = "Claro que puedes, pero entonces perderás el placer de haber resuelto un rompecabezas, Chubb.",
  ui_story_5026_50261402_26_dialog_content = "El Maestro debe saber cómo resolverlo. ¿Cachero?",
  ui_story_5026_50261402_27_option_content = "¡Por supuesto que sí!",
  ui_story_5026_50261402_28_dialog_content = "El orden es: agricultor, anciano, comerciante, erudito.",
  ui_story_5026_50261402_29_dialog_content = "¡Correcto! ¡Como se esperaba del Maestro!",
  ui_story_5026_50261402_30_option_content = "Este no es el momento para juegos.",
  ui_story_5026_50261402_31_dialog_content = "Cachero...",
  ui_story_5026_50261402_32_dialog_content = "Comencemos.",
  ui_story_5026_50261402_33_option_content = "Realizar enlace mental",
  ui_story_5026_50261402_34_dialog_content = "Clave secreta sintetizada. Nombre de inicio de sesión del operador: \"PlayerName\", Chubb.",
  ui_story_5026_50261402_35_dialog_content = "Verificación en curso. Por favor, agárrate al Chubb que ha tomado la forma de la Llave Secreta.",
  ui_story_5026_50261402_36_dialog_content = "¿Esta cosa en mi mano me está hablando?",
  ui_story_5026_50261402_37_dialog_content = "Es mucho más ligero de lo que parece.",
  ui_story_5026_50261402_38_dialog_content = "Verificación del operador completa, Chubb.",
  ui_story_5026_50261402_39_dialog_content = "No esperaba que siguiera hablando como un Chubb después de volverse así.",
  ui_story_5026_50261402_40_dialog_content = "No sé si debería llamarlo genial o lindo. Ninguno parece correcto.",
  ui_story_5026_50261402_41_dialog_content = "Las dos orejas puntiagudas en la punta parecen coincidir con la ranura del banco de trabajo.",
  ui_story_5026_50261402_42_dialog_content = "¿Puede... servir como arma también?",
  ui_story_5026_50261402_43_dialog_content = "Advertencia. No lo use para otros fines que no sean desbloquear la terminal de control de la Torre Hyacinth, Chubb.",
  ui_story_5026_50261402_44_dialog_content = "Coloque la llave secreta en la ranura para activar la conexión manual, Chubb.",
  ui_story_5026_50261402_45_dialog_content = "<color=#e8d9bb>¡Zumbido!</color>",
  ui_story_5026_50261402_46_dialog_content = "Conectado.",
  ui_story_5026_50261402_47_dialog_content = "Intentar establecer una conexión con el Obelisco del Retorno... Falló. Obelisco del Retorno offline.",
  ui_story_5026_50261402_48_dialog_content = "Estado del sistema de defensa: Deshabilitado.",
  ui_story_5026_50261402_49_dialog_content = "El operador y el terminal de control están en modo enlace mental.",
  ui_story_5026_50261402_50_dialog_content = "¿Cómo funciona exactamente este sistema de defensa?",
  ui_story_5026_50261402_51_dialog_content = "Recuperando documento de ayuda...",
  ui_story_5026_50261402_52_dialog_content = "El sistema de defensa activa un <color=#FFB400>campo de fuerza</color> que rodea la zona residencial con la Torre Jacinto en el centro.",
  ui_story_5026_50261402_53_dialog_content = "El campo de fuerza repelerá todas las formas de vida etiquetadas como hostiles.",
  ui_story_5026_50261402_54_dialog_content = "Un campo de fuerza que mantiene alejados a los enemigos...",
  ui_story_5026_50261402_55_dialog_content = "Está lejos del Acorde de la Ley, pero no es como si tuviéramos otra opción en este momento.",
  ui_story_5026_50261402_56_dialog_content = "Configuración de objetivo hostil actual: aurorianos.",
  ui_story_5026_50261402_57_dialog_content = "Por favor emita un comando.",
  ui_story_5026_50261402_58_dialog_content = "<size=45>¡¡¡!!!</size>",
  ui_story_5026_50261402_59_dialog_content = "Oye, PlayerName? ¿Hola?",
  ui_story_5026_50261402_60_dialog_content = "¡N-Nina! Puedo explicarlo. Lo que acabas de escuchar—",
  ui_story_5026_50261402_61_dialog_content = "No he oído nada desde que recogiste esa llave.",
  ui_story_5026_50261402_62_dialog_content = "Simplemente pusiste la llave sin decir una palabra, pero te veías tan sombrío, por eso yo...",
  ui_story_5026_50261402_63_dialog_content = "Tú... ¿no escuchaste nada?",
  ui_story_5026_50261402_64_dialog_content = "(Entonces, ¿la llave y la terminal se estaban comunicando conmigo telepáticamente?)",
  ui_story_5026_50261402_65_dialog_content = "(Tal vez así es como Caelestites se comunicaba con sus creaciones...)",
  ui_story_5026_50261402_66_dialog_content = "¿Es esto... un arma Caelestite?",
  ui_story_5026_50261402_67_dialog_content = "Se ve bastante único.",
  ui_story_5026_50261402_68_dialog_content = "Aunque es solo una llave, sé lo que quieres decir, Sanae.",
  ui_story_5026_50261402_69_dialog_content = "¡Cuatro Chubbs apilados juntos!",
  ui_story_5026_50261402_70_dialog_content = "¡Me está matando totalmente de ternura!",
  ui_story_5026_50261402_71_dialog_content = "(Derecha...)",
  ui_story_5026_50261402_72_dialog_content = "(Cualquiera que sea la verdad, no dudaré de las decisiones que he tomado).",
  ui_story_5026_50261402_73_dialog_content = "(Ahora, necesito volver a sumergirme en el enlace...)",
  ui_story_5026_50261402_74_dialog_content = "(Hmm... Es como... Una vez que notas que estás respirando, es difícil hacerlo naturalmente).",
  ui_story_5026_50261402_75_dialog_content = "(¡Enfoque!)",
  ui_story_5026_50261402_76_dialog_content = "Sistema Terminal, ¿puedes oírme?",
  ui_story_5026_50261402_77_dialog_content = "En espera de entrada de comando.",
  ui_story_5026_50261402_78_dialog_content = "Marca todos los eclipses como hostiles. Activa el sistema de defensa.",
  ui_story_5026_50261402_79_dialog_content = "Comando confirmado. Objetivo: Eclipses.",
  ui_story_5026_50261402_80_dialog_content = "Progreso de inicio de campo de fuerza: 36%... 67%... 100%.",
  ui_story_5026_50261402_81_dialog_content = "<color=#FFB400>Comienza la resonancia de la sonata</color>.",
  ui_story_5026_50261501_1_dialog_content = "¿Se acabó?",
  ui_story_5026_50261501_2_dialog_content = "Las marcas en la Torre Hyacinth brillaron, pero Cloud Gardens no parece ser diferente.",
  ui_story_5026_50261501_3_dialog_content = "¿Podría haber fallado? La tecnología es antigua, después de todo.",
  ui_story_5026_50261501_4_dialog_content = "Bueno... Aunque no puedo ver nada, puedo sentir que algo es diferente.",
  ui_story_5026_50261501_5_dialog_content = "El sistema de defensa está activado. Los eclipses no podrán acercarse al campo de fuerza, Chubb.",
  ui_story_5026_50261501_6_dialog_content = "Genial...",
  ui_story_5026_50261501_7_dialog_content = "Esto se aplica a los eclipses tanto fuera como dentro del campo de fuerza, Chubb.",
  ui_story_5026_50261501_8_dialog_content = "¿Qué? Así que si intentan evitar la pared del campo de fuerza, ¿no significa eso...?",
  ui_story_5026_50261501_9_dialog_content = "Se congregarán en el centro de Cloud Gardens, que está aquí en Hyacinth Tower, Chubb.",
  ui_story_5026_50261501_10_dialog_content = "¡Deberías haberme dicho eso antes de que activara las defensas!",
  ui_story_5026_50261501_11_dialog_content = "PlayerName no pregunte Cachero.",
  ui_story_5026_50261501_12_dialog_content = "Yo... estoy empezando a pensar que escondes una agenda debajo de tu linda fachada.",
  ui_story_5026_50261501_13_dialog_content = "No entiendo. ¿Vuelve, Chubb?",
  ui_story_5026_50261501_14_dialog_content = "Ya que estamos en el tema de la información importante, ¿de qué fuente de energía se nutre el sistema de defensa? No se quedará sin energía de repente, ¿verdad?",
  ui_story_5026_50261501_15_dialog_content = "La energía cinética generada por Chubbs mientras se mueve proporciona energía para otros Chubbs y la Torre Hyacinth. Cachero.",
  ui_story_5026_50261501_16_dialog_content = "Así que los Chubbs no habéis estado deambulando sin rumbo...",
  ui_story_5026_50261501_17_dialog_content = "En ese caso, ¿puede pelear Chubbs?",
  ui_story_5026_50261501_18_dialog_content = "Tal vez algo como combinarse para formar un Chubb gigante a través del enlace mental—",
  ui_story_5026_50261501_19_dialog_content = "Absolutamente no, Chubb.",
  ui_story_5026_50261501_20_dialog_content = "¡Eso fue un no rápido!",
  ui_story_5026_50261501_21_dialog_content = "Al menos no habrá más eclipses invadiendo este lugar, ¿verdad?",
  ui_story_5026_50261501_22_dialog_content = "Por lo tanto, no se vea tan molesto. Has hecho lo mejor que puedes, PlayerName.",
  ui_story_5026_50261501_23_dialog_content = "¿Es contratar mercenarios de Umbraton la única opción que tengo ahora...?",
  ui_story_5026_50261501_24_dialog_content = "Mis deudas siguen acumulándose. Vice se va a sorprender cuando regrese...",
  ui_story_5026_50261501_25_dialog_content = "Bueno, lo hice lo mejor que pude. No hay nada de qué quejarse.",
  ui_story_5026_50261501_26_dialog_content = "Si tan solo hubiera notado los problemas de seguridad de Cloud Gardens mucho antes, nada de esto habría sucedido.",
  ui_story_5026_50261501_27_dialog_content = "PlayerName.",
  ui_story_5026_50261501_28_dialog_content = "Señorita Nina, deberíamos regresar a Umbraton ahora.",
  ui_story_5026_50261501_29_dialog_content = "¿En este momento? Pero PlayerName está en un aprieto ahora mismo!",
  ui_story_5026_50261501_30_dialog_content = "Todo lo que queda por hacer es llegar al campo de fuerza y esperar la ayuda de Lady Bethel.",
  ui_story_5026_50261501_31_dialog_content = "Si eso se puede hacer, entonces los eclipses ya no deberían representar una amenaza.",
  ui_story_5026_50261501_32_dialog_content = "Perdóneme por ser franco, señorita, pero no hay nada más que usted y yo podamos hacer.",
  ui_story_5026_50261501_33_dialog_content = "¿¡Cómo puedes decir eso!? Eso es frío, incluso para ti, Minos.",
  ui_story_5026_50261501_34_dialog_content = "Incluso si no podemos matar a todos los Eclipsites, ¡debemos hacer lo que podamos antes de que lleguen los refuerzos!",
  ui_story_5026_50261501_35_dialog_content = "De lo contrario, PlayerName ¡Estaría arruinado, viviendo en las calles y vendiendo Chubbs para ganarse la vida!",
  ui_story_5026_50261501_36_dialog_content = "¡N-No llegará a eso! ... Pienso.",
  ui_story_5026_50261501_37_dialog_content = "El combate no es su fuerte, señorita Nina. ¿Cuánta ayuda puedes ser?",
  ui_story_5026_50261501_38_dialog_content = "No quiero verte lastimado en una pelea innecesaria.",
  ui_story_5026_50261501_39_dialog_content = "¿Una pelea innecesaria?",
  ui_story_5026_50261501_40_dialog_content = "Cualquier cosa PlayerName ¡Necesita ayuda con está lejos de ser innecesaria para mí!",
  ui_story_5026_50261501_41_dialog_content = "Dejar el trabajo a los profesionales es la solución más eficiente y eficaz.",
  ui_story_5026_50261501_42_dialog_content = "En otras palabras, ¿crees que soy tan frágil y débil que unos pocos eclipses me harían daño?",
  ui_story_5026_50261501_43_dialog_content = "Está tergiversando mis palabras, señorita. Solo le pido que cumpla su promesa.",
  ui_story_5026_50261501_44_dialog_content = "Si insistes, por favor convénceme a través de acciones.",
  ui_story_5026_50261501_45_dialog_content = "Multa. Si es lo que quieres.",
  ui_story_5026_50261501_46_dialog_content = "Saca tu arma.",
  ui_story_5026_50261501_47_dialog_content = "Te mostraré cuánto han mejorado mis habilidades de combate.",
  ui_story_5026_50261501_48_dialog_content = "Me alegra escucharlo. Sin embargo, no importaría incluso si todos ustedes se unieran contra mí.",
  ui_story_5026_50261501_49_option_content = "¿¡Cómo se llegó a esto!?",
  ui_story_5026_50261501_50_dialog_content = "¡N-Nina! ¡Te ayudare!",
  ui_story_5026_50261501_51_option_content = "¡Ya deja de pelear por mí!",
  ui_story_5026_50261501_52_dialog_content = "¡NO estamos peleando por ti! ¡Simplemente odio cómo siempre actúa como si estuviera haciendo lo mejor para mí!",
  ui_story_5026_50261501_53_dialog_content = "Parece que no tengo otra opción.",
  ui_story_5026_50261502_1_dialog_content = "Eso es aterrador... Atravesó el suelo como un cuchillo caliente a través de la mantequilla...",
  ui_story_5026_50261502_2_dialog_content = "¿Tiene suficiente munición, señorita?",
  ui_story_5026_50261502_3_dialog_content = "<size=45>¡Deja de subestimarme!</size>",
  ui_story_5026_50261502_4_dialog_content = "¡Te está provocando, Nina! ¡Este no es el momento!",
  ui_story_5026_50261502_5_dialog_content = "¡Sanae, cubre el lado derecho!",
  ui_story_5026_50261502_6_dialog_content = "G-Entendido! ¿Estás lista, Manae?",
  ui_story_5026_50261502_7_dialog_content = "¡No perdería la oportunidad de golpear a mi superior!",
  ui_story_5026_50261502_8_dialog_content = "Solo evade su próximo ataque—",
  ui_story_5026_50261502_9_dialog_content = "<size=45>¡Eso es todo! ¡En este momento!</size>",
  ui_story_5026_50261502_10_dialog_content = "Estoy exhausto...",
  ui_story_5026_50261502_11_dialog_content = "¿Qué tal ahora? H... *jadeos* ¿Ya has tenido suficiente?",
  ui_story_5026_50261502_12_dialog_content = "(Incluso si puedo predecir sus acciones hasta cierto punto a través de mi habilidad... Es difícil seguirle el ritmo.)",
  ui_story_5026_50261502_13_dialog_content = "(Fue una victoria reñida... Sólo puedo esperar no tener que volver a enfrentarme a Minos nunca más...)",
  ui_story_5026_50261502_14_dialog_content = "Estoy impresionado.",
  ui_story_5026_50261502_15_dialog_content = "Señorita Nina, Sanae y PlayerName...",
  ui_story_5026_50261502_16_dialog_content = "Su actuación superó mis expectativas.",
  ui_story_5026_50261502_17_dialog_content = "Cuánto tiempo ha pasado desde la última vez que probé la derrota...",
  ui_story_5026_50261502_18_dialog_content = "Felicitaciones, señorita Nina. Has ganado.",
  ui_story_5026_50261502_19_dialog_content = "Tanto esta batalla como nuestro trato.",
  ui_story_5026_50261502_20_dialog_content = "Si puedes vencerme en \"<color=#FFB400>sólo una cosa</color> en Cloud Gardens\", ganas.",
  ui_story_5026_50261502_21_dialog_content = "La batalla cumplió perfectamente con esas condiciones.",
  ui_story_5026_50261502_22_dialog_content = "Será mejor que tenga más cuidado al hacer un acuerdo verbal la próxima vez.",
  ui_story_5026_50261502_23_dialog_content = "Minus, tú...",
  ui_story_5026_50261502_24_dialog_content = "Por favor, tenga cuidado con su lenguaje, señorita. Mantenga siempre la elegancia de una dama.",
  ui_story_5026_50261502_25_dialog_content = "¡No he dicho nada todavía!",
  ui_story_5026_50261502_26_dialog_content = "Sí, no usé toda mi fuerza en nuestra batalla.",
  ui_story_5026_50261502_27_dialog_content = "Sin embargo, todavía has demostrado que eres capaz de cuidarte a ti mismo en este peligroso continente.",
  ui_story_5026_50261502_28_dialog_content = "Los compañeros que has elegido no son sirvientes, sino amigos que estarán a tu lado.",
  ui_story_5026_50261502_29_dialog_content = "Señor Minos...",
  ui_story_5026_50261502_30_dialog_content = "Informaré de esto al Maestro Andersen.",
  ui_story_5026_50261502_31_dialog_content = "Según nuestro acuerdo, debería despedirme de ti ahora, pero me siento muy apenado.",
  ui_story_5026_50261502_32_dialog_content = "Como se puede ver claramente, dañé severamente Cloud Gardens en nuestra batalla.",
  ui_story_5026_50261502_33_dialog_content = "Yo era un invitado, pero destruí PlayerNameLa casa de los Chubb y los Chubb...",
  ui_story_5026_50261502_34_dialog_content = "A pesar de que solo son mi empleador temporal y mis aprendices, he traicionado su confianza.",
  ui_story_5026_50261502_35_dialog_content = "Sr. Navegante, lamento mucho esto.",
  ui_story_5026_50261502_36_dialog_content = "Sé que no hay manera de que pueda compensarte por lo que le hice a las cosas que aprecias...",
  ui_story_5026_50261502_37_dialog_content = "Pero permítanme la oportunidad de compensar lo que he hecho restaurando Cloud Gardens.",
  ui_story_5026_50261502_38_dialog_content = "No te preocupes. Soy bastante bueno limpiando todas las manchas, basura y alimañas.",
  ui_story_5026_50261502_39_dialog_content = "Lo que, por supuesto, incluye a todos los invitados no deseados en Cloud Gardens.",
  ui_story_5026_50261502_40_dialog_content = "Quieres decir... ¿Te encargarás de todos los Eclipsites?",
  ui_story_5026_50261502_41_dialog_content = "¿No aceptas mi disculpa?",
  ui_story_5026_50261502_42_dialog_content = "Acepto, por supuesto. es solo—",
  ui_story_5026_50261502_43_dialog_content = "No hay necesidad de decir más. Solo quiero mostrar mi sinceridad.",
  ui_story_5026_50261502_44_dialog_content = "(¿Cómo es que siento que me han jugado...)",
  ui_story_5026_50261502_45_dialog_content = "(¿Pero en el buen sentido?)",
  ui_story_5026_50261502_46_dialog_content = "Debes estar cansado.",
  ui_story_5026_50261502_47_dialog_content = "Sanae, por favor, lleva a estos dos a la Torre Jacinto para que descansen. Ya he puesto la mesa allí.",
  ui_story_5026_50261502_48_dialog_content = "¡Sí señor!",
  ui_story_5026_50261502_49_dialog_content = "Um... Sr. Navegante, Nina.",
  ui_story_5026_50261502_50_dialog_content = "Supongo... ¿tomar una taza de té primero?",
  ui_story_5026_50261601_1_dialog_content = "Tal es el informe completo de mi viaje a Cloud Gardens.",
  ui_story_5026_50261601_2_dialog_content = "La misión fracasó por mi propia imprudencia. no tengo excusa",
  ui_story_5026_50261601_3_dialog_content = "Pero confío en que la señorita Nina tome sus propias decisiones.",
  ui_story_5026_50261601_4_dialog_content = "Su determinación y trabajo duro, pasión y persistencia, son como tú.",
  ui_story_5026_50261601_5_dialog_content = "Minos...",
  ui_story_5026_50261601_6_dialog_content = "¿Sí, señor?",
  ui_story_5026_50261601_7_dialog_content = "Cuando Nina era joven, corría por la mitad del patio solo para mostrarme una hermosa flor que había encontrado.",
  ui_story_5026_50261601_8_dialog_content = "Pero cuando creció, ni siquiera me dejaba comprarle nada de su trabajo.",
  ui_story_5026_50261601_9_dialog_content = "¿Es tan malo que yo quiera tener algo que ella misma diseñó y elaboró?",
  ui_story_5026_50261601_10_dialog_content = "Quería tener al menos dos juegos de cada tipo y color para mí... Un juego para colección, el otro juego para uso real.",
  ui_story_5026_50261601_11_dialog_content = "Más un conjunto más para hacer alarde frente a Istvan.",
  ui_story_5026_50261601_12_dialog_content = "Y tres juegos adicionales, en caso de que algo se dañe o se pierda en un accidente.",
  ui_story_5026_50261601_13_dialog_content = "Y enviar a alguien a comprarlos en secreto no fue un gran problema...",
  ui_story_5026_50261601_14_dialog_content = "Dejar que ella se enterara fue el único error que cometí.",
  ui_story_5026_50261601_15_dialog_content = "¡Lo sabía! ¡Realmente no has reflexionado sobre lo que hiciste en absoluto!",
  ui_story_5026_50261601_16_dialog_content = "Nina? ¿Estás de vuelta? Minos, ¿me engañan mis ojos?",
  ui_story_5026_50261601_17_dialog_content = "No, no lo son, Maestro.",
  ui_story_5026_50261601_18_dialog_content = "La única razón por la que no quería que compraras mis creaciones es porque tú...",
  ui_story_5026_50261601_19_dialog_content = "¡Siempre quieres andar haciendo alarde de mis creaciones medio decentes en cada reunión social!",
  ui_story_5026_50261601_20_dialog_content = "¡Es muy vergonzoso!",
  ui_story_5026_50261601_21_dialog_content = "Estás siendo demasiado modesto, querida. Nunca he sido más que veraz en mis halagos.",
  ui_story_5026_50261601_22_dialog_content = "Y, ¿era necesario comprar completamente mi tienda?",
  ui_story_5026_50261601_23_dialog_content = "Todos nuestros guardias y escoltas merecen tener un armamento tan estético como práctico.",
  ui_story_5026_50261601_24_dialog_content = "Solo quería enorgullecerte haciéndolo mejor que Bethel...",
  ui_story_5026_50261601_25_dialog_content = "Minos ya te fue de gran ayuda cuando tenía mi edad, ¿no?",
  ui_story_5026_50261601_26_dialog_content = "No necesitas probarme nada ni compararte con nadie más.",
  ui_story_5026_50261601_27_dialog_content = "He estado orgulloso de ti desde el momento de tu nacimiento.",
  ui_story_5026_50261601_28_dialog_content = "¡Pero también hay otras razones por las que quiero tener éxito!",
  ui_story_5026_50261601_29_dialog_content = "Quiero que mis diseños se conviertan en parte de la vida cotidiana de las personas.",
  ui_story_5026_50261601_30_dialog_content = "Para lograrlo, necesito comentarios reales de los clientes, ya sean buenos o malos.",
  ui_story_5026_50261601_31_dialog_content = "Esa es la única forma en que puedo impulsar mi negocio.",
  ui_story_5026_50261601_32_dialog_content = "<anim type=Shake>Nina... Realmente has crecido...</anim>",
  ui_story_5026_50261601_33_dialog_content = "<size=45>¿P-Por qué estás llorando?</size>Papá, por qué eres tan dramático... Me estás avergonzando.",
  ui_story_5026_50261601_34_dialog_content = "Ojalá tu madre hubiera oído lo que acabas de decir.",
  ui_story_5026_50261601_35_dialog_content = "Oh, ¿te dije que conocí a esta interesante Caelestite en Eraveil?",
  ui_story_5026_50261601_36_dialog_content = "Si no fuera por él, no me habría dado cuenta de mis defectos e inmadurez a la hora de iniciar un negocio.",
  ui_story_5026_50261601_37_dialog_content = "Tampoco me habría dado cuenta de que necesitaba tiempo para pensar y calmarme, y para ser honesto contigo sobre mis sentimientos.",
  ui_story_5026_50261601_38_dialog_content = "La forma en que trató desesperadamente de agarrar algo con sus propias manos...",
  ui_story_5026_50261601_39_dialog_content = "Me dio una idea de cómo me ves.",
  ui_story_5026_50261601_40_dialog_content = "¡Hmph! ¡Y tú! Aunque me di cuenta de tus verdaderos motivos de inmediato, ¡debo decir esto!",
  ui_story_5026_50261601_41_dialog_content = "¡La forma en que te burlaste de mí, Minos, realmente eres bueno para enojarme!",
  ui_story_5026_50261601_42_dialog_content = "Gracias por tu cumplido.",
  ui_story_5026_50261601_43_dialog_content = "¡Eso no fue un cumplido!",
  ui_story_5026_50261601_44_dialog_content = "Bien... Supongo que es en cierto modo.",
  ui_story_5026_50261601_45_dialog_content = "El Caelestite también tiene en su compañía a un montón de adorables Chubbs. Lástima que no pude traer uno conmigo...",
  ui_story_5026_50261601_46_dialog_content = "¡Y Sanae me enseñó a pescar! También...",
  ui_story_5026_50261601_47_dialog_content = "¡Vaya! Déjame quitarme lo que estoy usando ahora. ¡Vuelvo enseguida! ¡Mantén tu agenda clara para mí!",
  ui_story_5026_50261601_48_dialog_content = "Minos.",
  ui_story_5026_50261601_49_dialog_content = "¿Sí, señor?",
  ui_story_5026_50261601_50_dialog_content = "Quién es PlayerName?",
  ui_story_5026_50261601_51_dialog_content = "PlayerName Puede ser joven, pero sin embargo, es una persona de buen carácter.",
  ui_story_5026_50261601_52_dialog_content = "¡Hmph! No creo que Last Caelestite sea pacifista.",
  ui_story_5026_50261601_53_dialog_content = "Su habilidad innata les hace imposible evitar verse envueltos en asuntos mundanos.",
  ui_story_5026_50261601_54_dialog_content = "La honestidad y la bondad no son suficientes para garantizar la supervivencia en este mundo.",
  ui_story_5026_50261601_55_dialog_content = "Tienes razón.",
  ui_story_5026_50261601_56_dialog_content = "La única forma de mantener la paz es ser el que tiene el palo más grande.",
  ui_story_5026_50261601_57_dialog_content = "O... estando del lado del que sostiene el palo más grande.",
  ui_story_5026_50261601_58_dialog_content = "No importa todo eso... Estoy jubilado. Dejaré estas preocupaciones mundanas al Señor de las Sombras. Más importante...",
  ui_story_5026_50261601_59_dialog_content = "Mi querida Nina parece tener en alta estima a Caelestita y se preocupa por él. ¿Es eso cierto?",
  ui_story_5026_50261601_60_dialog_content = "Como de costumbre, todos los hombres en contacto con Miss Nina son investigados y observados minuciosamente.",
  ui_story_5026_50261601_61_dialog_content = "Tienes tres minutos. Quiero toda la información relacionada con ese niño, incluida cualquier cosa que pueda haber aparecido en el Umbraton Daily.",
  ui_story_5026_50261601_62_dialog_content = "Como desees.",
  ui_story_5026_50261601_63_dialog_content = "Hay tanto silencio.",
  ui_story_5026_50261601_64_dialog_content = "(No mucho después de que Minos se fue, Nina y Sanae también regresaron a Umbraton).",
  ui_story_5026_50261601_65_dialog_content = "(Espero que Nina pueda hacer las paces con su padre).",
  ui_story_5026_50261601_66_dialog_content = "(Aunque todavía no se ha dado por vencida con ese plan de dominación mundial suyo...)",
  ui_story_5026_50261601_67_dialog_content = "Hay muchas cosas que necesito resolver para integrar su idea de \"refugio seguro\" con mi plan.",
  ui_story_5026_50261601_68_dialog_content = "Esa fue la razón por la que inicialmente rechazaste mi plan, ¿verdad?",
  ui_story_5026_50261601_69_dialog_content = "Ser incapaz de ganarme la confianza de mi pareja demuestra lo inmaduro que soy.",
  ui_story_5026_50261601_70_dialog_content = "Si es así, ya no puedo perder el tiempo en este lugar tranquilo.",
  ui_story_5026_50261601_71_dialog_content = "He decidido regresar a casa y aprender administración de empresas de mi padre.",
  ui_story_5026_50261601_72_dialog_content = "Pero te prometo que regresaré para solicitar trabajar contigo una vez que haya aprendido todo lo que pueda.",
  ui_story_5026_50261601_73_dialog_content = "¡N-No te atrevas a olvidar!",
  ui_story_5026_50261601_74_dialog_content = "(¿Minos decidió decirme quién era Nina porque vio mi influencia en ella?)",
  ui_story_5026_50261601_75_dialog_content = "(Si es así... Entonces no solo estaba probando a Nina, sino también a mí...)",
  ui_story_5026_50261601_76_dialog_content = "(Tal vez había sido su plan todo el tiempo desde el momento en que nos conocimos).",
  ui_story_5026_50261601_77_dialog_content = "(Que aterrador es este mayordomo...)",
  ui_story_5026_50261601_78_dialog_content = "(Al final, no logré contratar a un gerente, pero los Chubb deberían poder ayudarme a cuidar de Cloud Gardens).",
  ui_story_5026_50261601_79_dialog_content = "(También he aprendido bastante desde que activé el sistema de defensa de la Torre Hyacinth).",
  ui_story_5026_50261601_80_dialog_content = "Ahora, entonces, debería comenzar con las tareas relacionadas con Cloud Gardens.",
  ui_story_5026_50261601_81_dialog_content = "Primero, eso... ¿cómo se llamaba, una lista de empleados?",
  ui_story_5026_50261601_82_dialog_content = "¿Por qué estás solo aquí? PlayerName? ¿Dónde están Nina y todos los demás?",
  ui_story_5026_50261601_83_dialog_content = "Muchos de tus amigos estuvieron dispuestos a ayudarte después de enterarse de tu situación.",
  ui_story_5026_50261601_84_dialog_content = "A pesar de que la mayoría de ellos no pudo asistir debido a compromisos anteriores, logré reclutar algo de ayuda.",
  ui_story_5026_50261601_85_dialog_content = "Pero parece que ya te has encargado de los eclipses.",
  ui_story_5026_50261601_86_dialog_content = "Es una larga historia... ¿No recibiste mi mensaje, Bethel?",
  ui_story_5026_50261601_87_dialog_content = "Te reembolsaré los gastos de transporte...",
  ui_story_5026_50261601_88_dialog_content = "No dude en ponerse en contacto conmigo si necesita un trabajo a realizar en el futuro.",
  ui_story_5026_50261601_89_dialog_content = "Nos ayudaste durante el incidente del Blue Lion Guild. Me gustaría mucho tener la oportunidad de devolverle el dinero.",
  ui_story_5026_50261601_90_dialog_content = "Sólo hice lo que debería haber hecho. no me debes nada...",
  ui_story_5026_50261601_91_dialog_content = "Eres demasiado amable, PlayerName.",
  ui_story_5026_50261601_92_dialog_content = "Entonces, piénselo así: ayudar a Last Caelestite a reconstruir su hogar y establecerse es bueno para la imagen de los Mercenarios de la Llama Blanca.",
  ui_story_5026_50261601_93_dialog_content = "Un ganar-ganar, por así decirlo.",
  ui_story_5026_50261601_94_dialog_content = "Ya veo. Gracias por su ayuda de antemano, entonces.",
  ui_story_5026_50261601_95_dialog_content = "Oh, ¿ya se tomaron todos los trabajos?",
  ui_story_5026_50261601_96_dialog_content = "Ya que estoy aquí, también podría hacer algunos negocios... Creo que una buena pintura iría bien con tu nuevo hogar. PlayerName.",
  ui_story_5026_50261601_97_dialog_content = "Como jefe, necesitas algo de arte para hacer que este lugar sea más sensual y mostrar tu gusto.",
  ui_story_5026_50261601_97X1_dialog_content = "Si no te gustan las pinturas, ¿qué tal una estatua de un artista de moda en Umbraton?",
  ui_story_5026_50261601_97X2_dialog_content = "Tsk, como canino, no puedo evitar admitir que está más dotado en el departamento de apariencia.",
  ui_story_5026_50261601_98_dialog_content = "Gracias pero no gracias.",
  ui_story_5026_50261601_99_dialog_content = "¡No digas eso! Echa un vistazo a este folleto. Todas estas son grandes pinturas de artistas de renombre...",
  ui_story_5026_50261601_100_dialog_content = "¡Wow!",
  ui_story_5026_50261601_101_dialog_content = "¿Es la casa de este cachorro? ¡Tan espacioso!",
  ui_story_5026_50261601_102_dialog_content = "No de Puppy, pero PlayerName's.",
  ui_story_5026_50261601_103_dialog_content = "¿El nuevo hogar de Puppy es más espacioso que el Colossus? ¡Me encantaría correr por aquí!",
  ui_story_5026_50261601_104_dialog_content = "¿Qué hay de las escondidas?",
  ui_story_5026_50261601_105_dialog_content = "¡Juguemos todos al escondite!",
  ui_story_5026_50261601_106_dialog_content = "¡Cuidado, ustedes dos! ¡No te topes con las cosas!",
  ui_story_5026_50261601_107_dialog_content = "Siéntase libre de chocar contra esos dos especuladores, pero tenga cuidado con las reliquias. Este lugar es una antigua ruina Caelestita.",
  ui_story_5026_50261601_108_dialog_content = "Las reliquias de caelestita son bastante raras incluso en Umbraton. Me imagino que cada uno de ellos haría una gran exhibición en mi futura tienda.",
  ui_story_5026_50261601_109_dialog_content = "Hay algunas cosas en el Museo, pero no sé si cuentan como reliquias.",
  ui_story_5026_50261601_110_dialog_content = "Aunque parece que ya no tenemos trabajo, valió la pena hacer este viaje solo para poder ver tu colección.",
  ui_story_5026_50261601_111_dialog_content = "¡Puedo mostrarte el camino! ¡Cachero!",
  ui_story_5026_50261601_112_dialog_content = "Vaya, mira esa buena proporción... Siento algo precioso en ti.",
  ui_story_5026_50261601_113_dialog_content = "¿Cachero?",
  ui_story_5026_50261601_114_dialog_content = "No importa el Museo. ¿Te importa si te reviso un poco?",
  ui_story_5026_50261601_115_dialog_content = "Caray, ese momento de paz de hace un momento fue como un sueño...",
  ui_story_5026_50261601_116_dialog_content = "Nada en ti es nunca aburrido, valiente Navegante.",
  ui_story_5026_50261601_117_dialog_content = "¡Kleken!",
  ui_story_5026_50261601_118_dialog_content = "¿Adónde en el mar embravecido te llevará esta nueva arca?",
  ui_story_5026_50261601_119_dialog_content = "¡Los jardines del cielo que se sumergen profundamente en el océano deben ser una vista para la vista!",
  ui_story_5026_50261601_120_dialog_content = "Haré todo lo posible para nunca dejar que eso suceda...",
  ui_story_5026_50261601_121_dialog_content = "Ja... ¿De qué locura está hablando esta vez?",
  ui_story_5026_50261601_122_dialog_content = "Tú también, PlayerName. Todavía te ves tan torpe como siempre.",
  ui_story_5026_50261601_123_dialog_content = "Hidra? No pensé que estarías aquí también—",
  ui_story_5026_50261601_124_dialog_content = "Adiós.",
  ui_story_5026_50261601_125_dialog_content = "¡Acabas de llegar!",
  ui_story_5026_50261601_126_dialog_content = "¡No es como si quisiera venir! Ese estúpido pulpo me mintió sobre cómo el jefe me necesitaba aquí para un trabajo.",
  ui_story_5026_50261601_127_dialog_content = "Es demasiado ancho y abierto aquí. Está inquietando a los Lobos Sombríos, como esos perros de allí.",
  ui_story_5026_50261601_128_dialog_content = "No se puede evitar. ¡Está en nuestra naturaleza!",
  ui_story_5026_50261601_129_dialog_content = "<size=40>¡Vamos! ¡Vamos! ¡Vamos a jugar a las escondidas!</size>",
  ui_story_5026_50261601_130_dialog_content = "<size=45>¡Fufufu!</size>",
  ui_story_5026_50261601_131_dialog_content = "<size=50>¡Es tan ruidoso! ¡Alejarse de mí!</size>",
  ui_story_5026_50261601_132_dialog_content = "... No esperaba que las cosas salieran así.",
  ui_story_5026_50261601_133_dialog_content = "Coloréame sorprendido. Sin un trabajo que hacer, los profesionales de Umbraton son solo un grupo de niños problemáticos.",
  ui_story_5026_50261601_134_dialog_content = "¿No es agradable ver cachorros jugando y persiguiéndose en un campo?",
  ui_story_5026_50261601_135_dialog_content = "Parece que esta conmoción no va a terminar por un tiempo.",
  ui_story_5026_50261601_136_dialog_content = "Er... Si ustedes no tienen prisa...",
  ui_story_5026_50261601_137_dialog_content = "¿Por qué no te sientas a tomar un té?",
  ui_story_5026_50261601_138_dialog_content = "<color=#e8d9bb>En el Puente de Soroz, unos días después</color>",
  ui_story_5026_50261601_139_dialog_content = "Así que... pasaste por todas estas cosas mientras no estábamos, ¿eh?",
  ui_story_5026_50261601_140_dialog_content = "Me alegro por ti, pero también me siento un poco deprimido por alguna razón.",
  ui_story_5026_50261601_141_dialog_content = "Vice...",
  ui_story_5026_50261601_142_dialog_content = "¡Será mejor que me muestres la Chubb Sword si alguna vez tienes la oportunidad de volver a hacerla en el futuro!",
  ui_story_5026_50261601_143_dialog_content = "¿¡Te sientes mal por eso!?",
  ui_story_5026_50261601_144_dialog_content = "Un campo de fuerza... No sabía que la Torre Jacinto podía hacer eso.",
  ui_story_5026_50261601_145_dialog_content = "La seguridad de Cloud Gardens era algo que me preocupaba.",
  ui_story_5026_50261601_146_dialog_content = "Afortunadamente, todo se resolvió antes de que se produjera un daño permanente.",
  ui_story_5026_50261601_147_dialog_content = "Defendiste tu casa por tu cuenta. Buen trabajo, PlayerName.",
  ui_story_5026_50261601_148_dialog_content = "Gracias, Carleen.",
  ui_story_5026_50261601_149_dialog_content = "Pero no lo hice solo. No podría haberlo hecho sin Nina y todos los demás.",
  ui_story_5026_50261601_150_dialog_content = "Al igual que Cloud Gardens no estaría aquí ahora mismo sin la ayuda de todos.",
  ui_story_5026_50261601_151_dialog_content = "...",
  ui_story_5026_50261601_152_dialog_content = "Después de aprender lo que hice sobre los Caelestites del Obelisco del Retorno y los Jardines de las Nubes...",
  ui_story_5026_50261601_153_dialog_content = "Me desencanté de mi pueblo y dudé de mí mismo.",
  ui_story_5026_50261601_154_dialog_content = "Pero luchar junto a ustedes y todos los demás aurorianos me hizo darme cuenta de algo.",
  ui_story_5026_50261601_155_dialog_content = "No es mi linaje o mi habilidad lo que define quién soy.",
  ui_story_5026_50261601_156_dialog_content = "Es mi propia voluntad y elecciones.",
